window.__TSD_ARTICLES__ = {"1257085":"<p><a href=\"https://thestandard.co/tag/%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%81%E0%B8%B5%E0%B8%AC%E0%B8%B2%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B9%80%E0%B8%97%E0%B8%A8%E0%B9%84%E0%B8%97%E0%B8%A2-(%E0%B8%81%E0%B8%81%E0%B8%97.)/\" target=\"_blank\" rel=\"noopener\">การกีฬาแห่งประเทศไทย</a> (กกท.) เปิดศูนย์ปฏิบัติงานให้บริการด้านวิทยาศาสตร์การกีฬา และศูนย์อำนวยการคณะนักกีฬาไทย ที่เมืองนาโกยา ประเทศญี่ปุ่น เพื่อสนับสนุนทัพนักกีฬาไทยตลอดการแข่งขันเอเชียนเกมส์ ครั้งที่ 20</p>\n<p>พิธีเปิดจัดขึ้นเมื่อวันที่ 19 กันยายน โดยมี วนิดา พันธ์สะอาด รองปลัดกระทรวงการท่องเที่ยวและกีฬา เป็นประธาน พร้อมด้วยผู้บริหารคณะกรรมการโอลิมปิคแห่งประเทศไทยฯ, กกท. และคณะนักกีฬาทีมชาติไทย</p>\n<p>ศูนย์ดังกล่าวจะเป็นจุดกลางในการประสานงานระหว่างแพทย์ นักวิทยาศาสตร์การกีฬา นักกายภาพบำบัด นักโภชนาการ นักจิตวิทยาการกีฬา และผู้ฝึกสอน เพื่อดูแลความพร้อมของนักกีฬาทั้งด้านร่างกายและจิตใจ รวมถึงการป้องกันอาการบาดเจ็บและฟื้นฟูร่างกายระหว่างการแข่งขัน</p>\n<p>นอกจากนี้ ศูนย์ยังทำหน้าที่ติดตามและประเมินสภาพนักกีฬา พร้อมเก็บรวบรวมข้อมูลเพื่อนำไปพัฒนาระบบวิทยาศาสตร์การกีฬาของไทยในอนาคต</p>\n<p>สำหรับเอเชียนเกมส์ 2026 ประเทศไทยส่งคณะนักกีฬาและเจ้าหน้าที่จาก 46 สมาคมกีฬา รวม 966 คน แบ่งเป็นนักกีฬาชาย 354 คน นักกีฬาหญิง 336 คน และเจ้าหน้าที่ 276 คน โดยศูนย์แห่งนี้จะทำหน้าที่สนับสนุนทัพไทยตลอดช่วงการแข่งขันที่ประเทศญี่ปุ่น</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/sat-sports-science-nagoya-2026-1.jpg\" alt=\"ภาพพิธีเปิดศูนย์วิทยาศาสตร์การกีฬาของ กกท. ที่เมืองนาโกยา ประเทศญี่ปุ่น โดยมีผู้บริหารและนักกีฬาร่วมงาน 1\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/sat-sports-science-nagoya-2026-2.jpg\" alt=\"ภาพพิธีเปิดศูนย์วิทยาศาสตร์การกีฬาของ กกท. ที่เมืองนาโกยา ประเทศญี่ปุ่น โดยมีผู้บริหารและนักกีฬาร่วมงาน 2\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/sat-sports-science-nagoya-2026-3.jpg\" alt=\"ภาพพิธีเปิดศูนย์วิทยาศาสตร์การกีฬาของ กกท. ที่เมืองนาโกยา ประเทศญี่ปุ่น โดยมีผู้บริหารและนักกีฬาร่วมงาน 3\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/sat-sports-science-nagoya-2026-4.jpg\" alt=\"ภาพพิธีเปิดศูนย์วิทยาศาสตร์การกีฬาของ กกท. ที่เมืองนาโกยา ประเทศญี่ปุ่น โดยมีผู้บริหารและนักกีฬาร่วมงาน 4\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/sat-sports-science-nagoya-2026-5.jpg\" alt=\"ภาพพิธีเปิดศูนย์วิทยาศาสตร์การกีฬาของ กกท. ที่เมืองนาโกยา ประเทศญี่ปุ่น โดยมีผู้บริหารและนักกีฬาร่วมงาน 5\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/sat-sports-science-nagoya-2026-6.jpg\" alt=\"ภาพพิธีเปิดศูนย์วิทยาศาสตร์การกีฬาของ กกท. ที่เมืองนาโกยา ประเทศญี่ปุ่น โดยมีผู้บริหารและนักกีฬาร่วมงาน 6\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/sat-sports-science-nagoya-2026-7.jpg\" alt=\"ภาพพิธีเปิดศูนย์วิทยาศาสตร์การกีฬาของ กกท. ที่เมืองนาโกยา ประเทศญี่ปุ่น โดยมีผู้บริหารและนักกีฬาร่วมงาน 7\" width=\"850\" height=\"550\" /></p>","1256968":"<p><a href=\"https://thestandard.co/tag/Real-Betis/\" target=\"_blank\" rel=\"noopener\">เรอัล เบติส</a> สร้างช่วงเวลาพิเศษก่อนเกมพบกับ โอซาซูนา ด้วยการเชิญสมาชิกสโมสรที่มีอายุมากที่สุด 11 คน เดินลงสนามเคียงข้างนักเตะก่อนเริ่มการแข่งขัน</p>\n<p>สมาชิกทั้ง 11 คนมีอายุมากกว่า 80 ปี และเป็นแฟนบอลที่อยู่เคียงข้างสโมสรมายาวนาน ผ่านทั้งช่วงเวลาที่ประสบความสำเร็จและช่วงเวลาที่ยากลำบากร่วมกับทีม</p>\n<p>กิจกรรมครั้งนี้สะท้อนอีกหนึ่งภาพเรียบง่าย แต่เต็มไปด้วยความหมายของฟุตบอล</p>\n<p><span><strong>ภาพ:</strong><span> realbetisbalompie / Instagram</span></span></p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/real-betis-senior-members-field-walk-1.jpg\" alt=\"ภาพสมาชิกอาวุโสของสโมสรเรอัล เบติส เดินลงสนามเคียงข้างนักฟุตบอล 1\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/real-betis-senior-members-field-walk-2.jpg\" alt=\"ภาพสมาชิกอาวุโสของสโมสรเรอัล เบติส เดินลงสนามเคียงข้างนักฟุตบอล 2\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/real-betis-senior-members-field-walk-3.jpg\" alt=\"ภาพสมาชิกอาวุโสของสโมสรเรอัล เบติส เดินลงสนามเคียงข้างนักฟุตบอล 3\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/real-betis-senior-members-field-walk-4.jpg\" alt=\"ภาพสมาชิกอาวุโสของสโมสรเรอัล เบติส เดินลงสนามเคียงข้างนักฟุตบอล 4\" width=\"1080\" height=\"1350\" /></p>","1256953":"<p>ทัพนักกีฬาขี่ม้าทีมชาติไทยพร้อมม้าคู่ใจเดินทางถึงประเทศญี่ปุ่นเป็นที่เรียบร้อย เตรียมลงแข่งขันกีฬา<a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ ครั้งที่ 20 Aichi-Nagoya 2026</a> โดยประเทศไทยส่งนักกีฬาเข้าร่วมทั้งหมด 8 คน ใน 2 ประเภท ได้แก่ ศิลปะบังคับม้า (Dressage) และอีเวนติ้ง (Eventing)</p>\n<p>นักกีฬาและม้าทีมชาติไทยเดินทางถึงญี่ปุ่นตั้งแต่วันที่ 15 กันยายน เพื่อให้ม้าได้พักฟื้นและปรับตัวจากการเดินทาง ก่อนเข้าสู่การฝึกซ้อมและเตรียมความพร้อมขั้นสุดท้าย</p>\n<p>ประเภทศิลปะบังคับม้า ทีมไทยประกอบด้วย สมเด็จพระเจ้าลูกเธอ เจ้าฟ้าสิริวัณณวรี นารีรัตนราชกัญญา กับม้า Boulevard, เฉลิมฉาน ยศวีระพาณิชย์ กับม้า Sant Jordi 3, ฉันชนก คลารา รึคเคอร์ กับม้า Vincent 186 และ นิร พุทธิสมบัติ กับม้า Rock That Tango</p>\n<p>ขณะที่ประเภทอีเวนติ้ง ประกอบด้วย กรธวัช สำราญ กับม้า B.Grimm Billy Elmy, พันตรี สุภาพ ขาวงาม กับม้า Vinetto 3, วรภัทร สิทธิจู กับม้า B.Grimm Uster de Chanay และ วีรภัฏ ปฏิกานนท์ กับม้า B.Grimm Carnival March</p>\n<p>นอกจากนี้ เฉลิมฉาน ยศวีระพาณิชย์ ยังได้รับหน้าที่เป็นหนึ่งในผู้ถือธงชาติไทยนำทัพนักกีฬาเข้าสู่พิธีเปิดเอเชียนเกมส์ 2026 วันที่ 19 กันยายน ร่วมกับ ทัดดาว นึกแจ้ง นักวอลเลย์บอลหญิงทีมชาติไทย</p>\n<p>สำหรับโปรแกรมแข่งขัน ทีมอีเวนติ้งไทยจะประเดิมสนามวันที่ 21 กันยายน โดยต้องแข่งขันครบ 3 บททดสอบ ทั้งศิลปะบังคับม้า ครอสคันทรี และกระโดดข้ามเครื่องกีดขวาง ก่อนที่ประเภทศิลปะบังคับม้าจะลงแข่งขันระหว่างวันที่ 25-27 กันยายน</p>\n<p>การแข่งขันกีฬาขี่ม้าจะจัดขึ้นที่ Equestrian Park เขตเซตากายะ กรุงโตเกียว สนามที่เคยใช้ในการแข่งขันโอลิมปิกมาแล้ว 2 ครั้ง ในปี 1964 และ 2021</p>\n<p>โดย ดร.ฮาราลด์ ลิงค์ นายกสมาคมกีฬาขี่ม้าแห่งประเทศไทยฯ ระบุว่า นักกีฬา ม้า ผู้ฝึกสอน สัตวแพทย์ และทีมงานได้เตรียมความพร้อมอย่างเต็มที่ พร้อมหวังให้นักกีฬาไทยแสดงศักยภาพออกมาได้ดีที่สุด โดยยังให้ความสำคัญกับสุขภาพและสวัสดิภาพของม้าเป็นอันดับแรก</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-equestrian-japan-asian-games-1.jpg\" alt=\"สมเด็จพระเจ้าลูกเธอ เจ้าฟ้าสิริวัณณวรี นารีรัตนราชกัญญา ทรงนำทัพนักกีฬาขี่ม้าทีมชาติไทยเดินทางถึงประเทศญี่ปุ่น เพื่อเตรียมแข่งขันเอเชียนเกมส์ 2026 1\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-equestrian-japan-asian-games-2.jpg\" alt=\"สมเด็จพระเจ้าลูกเธอ เจ้าฟ้าสิริวัณณวรี นารีรัตนราชกัญญา ทรงนำทัพนักกีฬาขี่ม้าทีมชาติไทยเดินทางถึงประเทศญี่ปุ่น เพื่อเตรียมแข่งขันเอเชียนเกมส์ 2026 2\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-equestrian-japan-asian-games-3.jpg\" alt=\"สมเด็จพระเจ้าลูกเธอ เจ้าฟ้าสิริวัณณวรี นารีรัตนราชกัญญา ทรงนำทัพนักกีฬาขี่ม้าทีมชาติไทยเดินทางถึงประเทศญี่ปุ่น เพื่อเตรียมแข่งขันเอเชียนเกมส์ 2026 3\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-equestrian-japan-asian-games-4.jpg\" alt=\"สมเด็จพระเจ้าลูกเธอ เจ้าฟ้าสิริวัณณวรี นารีรัตนราชกัญญา ทรงนำทัพนักกีฬาขี่ม้าทีมชาติไทยเดินทางถึงประเทศญี่ปุ่น เพื่อเตรียมแข่งขันเอเชียนเกมส์ 2026 4\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-equestrian-japan-asian-games-5.jpg\" alt=\"สมเด็จพระเจ้าลูกเธอ เจ้าฟ้าสิริวัณณวรี นารีรัตนราชกัญญา ทรงนำทัพนักกีฬาขี่ม้าทีมชาติไทยเดินทางถึงประเทศญี่ปุ่น เพื่อเตรียมแข่งขันเอเชียนเกมส์ 2026 5\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-equestrian-japan-asian-games-6.jpg\" alt=\"สมเด็จพระเจ้าลูกเธอ เจ้าฟ้าสิริวัณณวรี นารีรัตนราชกัญญา ทรงนำทัพนักกีฬาขี่ม้าทีมชาติไทยเดินทางถึงประเทศญี่ปุ่น เพื่อเตรียมแข่งขันเอเชียนเกมส์ 2026 6\" width=\"850\" height=\"550\" /></p>","1256910":"<p><a href=\"https://thestandard.co/tag/%E0%B8%A7%E0%B8%AD%E0%B8%A5%E0%B9%80%E0%B8%A5%E0%B8%A2%E0%B9%8C%E0%B8%9A%E0%B8%AD%E0%B8%A5%E0%B8%AB%E0%B8%8D%E0%B8%B4%E0%B8%87%E0%B8%97%E0%B8%B5%E0%B8%A1%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B9%84%E0%B8%97%E0%B8%A2/\" target=\"_blank\" rel=\"noopener\">วอลเลย์บอลหญิงทีมชาติไทย</a>ลงสนามพบกับไชนีสไทเป ในศึกเอเชียนเกมส์ 2026 รอบแบ่งกลุ่ม กลุ่ม C ก่อนเอาชนะไป 3-0 เซ็ต (25-22, 25-22, 25-20) พร้อมผ่านเข้าสู่รอบ 8 ทีมสุดท้าย</p>\n<p>แม้ผลการแข่งขันจะจบลงด้วยชัยชนะ 3 เซ็ตรวด แต่รูปเกมไม่ง่ายสำหรับทีมสาวไทย โดยวันนี้มีข้อผิดพลาดเกิดขึ้นค่อนข้างมาก</p>\n<p>ขณะที่ไชนีสไทเปเตรียมแผนมารับมือได้ดี ทำให้ไทยต้องเจอกับเกมที่สูสีและลุ้นถึงช่วงท้ายในแต่ละเซ็ต ก่อนอาศัยจังหวะสำคัญปิดเกมและเก็บชัยชนะได้สำเร็จ</p>\n<p>สำหรับวอลเลย์บอลหญิงทีมชาติไทยจะลงสนามในรอบ 8 ทีมสุดท้าย วันที่ 20 กันยายนนี้ โดยรอติดตามคู่แข่งขันและโปรแกรมการแข่งขันต่อไป</p>\n<p><span><strong>ภาพ:</strong><span> ดิษยุตม์ ธนบุญชัย</span></span></p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-1-1.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 1\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-2.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 2\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-3.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 3\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-4.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 4\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-5.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 5\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-6.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 6\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-7.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 7\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-8.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 8\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thailand-volleyball-asiangames-2026-9.jpg\" alt=\"ภาพนักวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับไชนีสไทเปในเอเชียนเกมส์ 2026 9\" width=\"850\" height=\"1080\" /></p>","1256897":"<p><a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a> เตรียมเปิดฉากอย่างเป็นทางการวันนี้ (19 กันยายน) ที่เมืองนาโกย่า ประเทศญี่ปุ่น นับเป็นการกลับมาจัดมหกรรมกีฬาแห่งเอเชียบนแผ่นดินญี่ปุ่นอีกครั้งในรอบ 32 ปี</p>\n<p>ตลอดวันมีกิจกรรมให้ติดตามตั้งแต่การบินของ Blue Impulse, Warm-up Stage ที่มี INI ร่วมแสดง ไปจนถึงขบวนพาเหรดนักกีฬาและการจุดคบเพลิงจาก ‘3 เปลวไฟ’</p>\n<p>THE STANDARD SPORT ชวนเช็ก OPENING DAY GUIDE ว่าวันพิธีเปิดเอเชียนเกมส์ 2026 มีอะไรให้ติดตามบ้าง ก่อนพิธีเปิดอย่างเป็นทางการจะเริ่มขึ้นในเวลา 16.00 น. ตามเวลาประเทศไทย</p>\n<p><span><b><span><strong>อ้างอิง:</strong></span></b></span></p>\n<ul>\n<li><span><a href=\"https://www.olympics.com/ja/news/asian-games-2026-opening-ceremony-broadcast-schedule-live-streams-preview?utm_&lt;span style=\" target=\"_blank\" rel=\"noopener\"><span>https://www.olympics.com/ja/news/asian-games-2026-opening-ceremony-broadcast-schedule-live-streams-preview?utm_source=chatgpt.com</span></a></span></li>\n<li><span><a href=\"https://www.aichi-nagoya2026.org/information-for-visitors/?utm_&lt;span style=\" target=\"_blank\" rel=\"noopener\"><span>https://www.aichi-nagoya2026.org/information-for-visitors/?utm_source=chatgpt.com</span></a></span></li>\n</ul>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-opening-1-1.jpg\" alt=\"ภาพปราสาทนาโกย่า ประเทศญี่ปุ่น 1\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-opening-2.jpg\" alt=\"ภาพปราสาทนาโกย่า ประเทศญี่ปุ่น 2\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-opening-3.jpg\" alt=\"ภาพปราสาทนาโกย่า ประเทศญี่ปุ่น 3\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-opening-4.jpg\" alt=\"ภาพปราสาทนาโกย่า ประเทศญี่ปุ่น 4\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-opening-5.jpg\" alt=\"ภาพปราสาทนาโกย่า ประเทศญี่ปุ่น 5\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-opening-6.jpg\" alt=\"ภาพปราสาทนาโกย่า ประเทศญี่ปุ่น 6\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-opening-7.jpg\" alt=\"ภาพปราสาทนาโกย่า ประเทศญี่ปุ่น 7\" width=\"1080\" height=\"1350\" /></p>","1256841":"<p>🇹🇭 โปรแกรมเอเชียนเกมส์วันนี้</p>\n<p>เช้าวันนี้ร่วมส่งกำลังใจให้บาสเกตบอลหญิงทีมชาติไทย ลงสนามพบกับทีมชาติจีน เวลา 08.00 น. ก่อนต่อด้วยการแข่งขัน เทคบอล 3 ประเภทในรอบรองชนะเลิศ ที่ทัพไทยมีลุ้นผ่านเข้าสู่รอบชิงชนะเลิศ</p>\n<p>จากนั้นช่วงเย็น เตรียมชมพิธีเปิดการแข่งขันเอเชียนเกมส์ 2026 อย่างเป็นทางการ ในเวลา 16.00 น. ร่วมเปิดฉากมหกรรมกีฬาครั้งสำคัญของเอเชีย ก่อนเข้าสู่การแข่งขันเต็มรูปแบบตลอดทัวร์นาเมนต์</p>\n<p>📺 ตลอดทัวร์นาเมนต์ รับชมการถ่ายทอดสดผ่านทีวีดิจิทัล 7 ช่อง</p>\n<p>NBT | T Sports 7 | 9 MCOT HD | ONE 31 | MONOMAX SPORTS TV | ไทยรัฐ TV 32 | PPTV HD 36</p>\n<p>📱 ออนไลน์ทาง AIS PLAY</p>\n<p>ถ่ายทอดสดสูงสุด 17 ช่อง พร้อมรับชมไฮไลต์และการแข่งขันย้อนหลัง</p>\n<p>ติดตามโปรแกรมการแข่งขันและเช็กโปรแกรมได้ที่นี่! 👇</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-sept-19-schedule-1.jpg\" alt=\"ภาพกราฟิกโปรแกรมการแข่งขันเอเชียนเกมส์ 2026 วันที่ 19 กันยายน พร้อมโลโก้ช่องถ่ายทอดสด 1\" width=\"1080\" height=\"1350\" /></p>","1256832":"<p>Olympics ทำคอนเทนต์ “ASIAN GAMES 2026: THE CONTINENT’S STARS TAKE CENTRE STAGE” รวบรวมนักกีฬาระดับแนวหน้าของเอเชียที่น่าจับตามองในศึก<a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a> ที่ไอจิ-นาโกยา ประเทศญี่ปุ่น โดยมีชื่อของ ‘บิว’ ภูริพล บุญสอน นักกรีฑาทีมชาติไทย เป็นหนึ่งในนั้น</p>\n<p>ภูริพลถูกเลือกให้อยู่ร่วมกับนักกีฬาชั้นนำของทวีป อาทิ อเล็กซานดรา เอียลา นักเทนนิสจากฟิลิปปินส์, คาร์ลอส ยูโล นักยิมนาสติกจากฟิลิปปินส์, อัน เซยอง นักแบดมินตันจากเกาหลีใต้, ฮาชิโมโตะ ไดกิ นักยิมนาสติกจากญี่ปุ่น และอีกหลายคน</p>\n<p>Olympics นิยามถึงลมกรดวัย 20 ปีของไทยว่า “นักวิ่งชาวไทยกลายเป็นนักกีฬาชายจากเอเชียตะวันออกเฉียงใต้คนแรกที่วิ่ง 100 เมตรต่ำกว่า 10 วินาที (9.94 วินาที) และด้วยวัยเพียง 20 ปี เขาคือหนึ่งในดาวรุ่งที่กำลังมาแรง”</p>\n<p>ผลงานดังกล่าวเกิดขึ้นจากการแข่งขันซีเกมส์ 2025 เมื่อภูริพลวิ่ง 100 เมตรด้วยเวลา 9.94 วินาที ทำลายกำแพง 10 วินาที พร้อมสร้างสถิติประเทศไทย ก่อนที่ในปี 2026 จะทำสถิติประเทศไทยในระยะ 200 เมตรเพิ่มอีกหนึ่งรายการ ด้วยเวลา 20.03 วินาที</p>\n<p>เอเชียนเกมส์ครั้งนี้ ภูริพลมีโปรแกรมลงแข่งขัน 3 รายการ ได้แก่ 100 เมตรชาย, 200 เมตรชาย และผลัด 4×100 เมตรชาย โดยการแข่งขันกรีฑาจะมีขึ้นระหว่างวันที่ 23-29 กันยายน ที่ Nagoya City Mizuho Park Athletic Stadium</p>\n<p>เป้าหมายของภูริพลคือการลุ้นเหรียญทองทั้ง 100 และ 200 เมตร พร้อมหวังทำลายสถิติของตัวเองอีกครั้ง ส่วนประเภทผลัด 4×100 เมตรชาย ตั้งเป้าพาทีมไทยขึ้นโพเดียม</p>\n<p>สำหรับเอเชียนเกมส์ครั้งก่อนที่หางโจว ภูริพลคว้าเหรียญเงิน 100 เมตรชาย ด้วยเวลา 10.02 วินาที ตามหลัง เซี่ย เจิ้นเย่ จากจีน เจ้าของเหรียญทอง ก่อนกลับมาในปี 2026 ด้วยสถานะที่ต่างออกไป หลังพัฒนาสถิติจนกลายเป็นนักวิ่งจากอาเซียนคนแรกที่วิ่ง 100 เมตรต่ำกว่า 10 วินาที</p>","1256688":"<p>กว่า 9 ปีบนเส้นทางสายนักสู้ของ แอมป์-กัญจุฑา ภัทรบุญซ่อน เต็มไปด้วยทั้งความสำเร็จและบททดสอบ จากนักมวยไทยอาชีพสู่แชมป์โลก<a href=\"https://thestandard.co/tag/%E0%B8%A2%E0%B8%B9%E0%B8%A2%E0%B8%B4%E0%B8%95%E0%B8%AA%E0%B8%B9/\" target=\"_blank\" rel=\"noopener\">ยูยิตสู</a> 3 สมัย แต่ลึกลงไปในชัยชนะเหล่านั้น สิ่งที่เธอทำกลับเป็นเพียง ‘หน้าที่’ มากกว่าสิ่งที่หัวใจรัก</p>\n<h2>PLAYER Profile: กัญจุฑา ภัทรบุญซ่อน</h2>\n \n\n<ul>\n<li><a href=\"#section1\" target=\"_blank\" rel=\"noopener\">เส้นทาง 9 ปี กว่าหน้าที่และความรักจะเดินทางมาพบกัน</a></li>\n<li><a href=\"#section2\" target=\"_blank\" rel=\"noopener\">ละทิ้งอีโก้ เพื่อเริ่มต้นใหม่ที่แท้จริง</a></li>\n<li><a href=\"#section3\" target=\"_blank\" rel=\"noopener\">เมื่อชัยชนะไม่ใช่เป้าหมายเดียวของการมีชีวิต</a></li>\n<li><a href=\"#section4\" target=\"_blank\" rel=\"noopener\">คู่แข่งสำคัญ</a></li>\n<li><a href=\"#section5\" target=\"_blank\" rel=\"noopener\">MMA แข่งที่ไหน ชิงกี่เหรียญทอง</a></li>\n</ul>\n\n<p> <br />\n </p>\n<p>จนวันหนึ่ง แอมป์ตัดสินใจวางทั้งสถานะและความสำเร็จ ยอมทิ้งอีโก้เพื่อกลับมาเป็น ‘มือใหม่’ บนเส้นทาง MMA จากวันแรกที่ซ้อมจนถึงขั้นอ้วกแตก วันนี้เธอกลายเป็นแชมป์โลกบนสังเวียนแห่งความฝัน และกลายเป็นดาวดวงใหม่ ความหวังเหรียญรางวัลรุ่น 54 กิโลกรัมหญิงของทัพนักกีฬาไทยในเอเชียนเกมส์ ครั้งที่ 20</p>\n<p>ทว่าสิ่งที่เธอค้นพบบนเส้นทางนักสู้ MMA ไม่ได้มีเพียงชัยชนะ หากคือบทเรียนที่ทำให้รู้จักปล่อยวาง ยอมรับความไม่แน่นอน และเข้าใจว่า การต่อสู้ที่สำคัญที่สุด อาจไม่ใช่การเอาชนะใคร แต่คือการได้เป็นตัวเองและทำในสิ่งที่รัก</p>\n<h2>เส้นทาง 9 ปี กว่าหน้าที่และความรักจะเดินทางมาพบกัน</h2>\n<p>ตลอดเส้นทางกว่า 9 ปีในฐานะนักกีฬา แอมป์พูดได้เต็มปากว่า ชีวิตบนสังเวียนที่ผ่านมา ‘สะบักสะบอม’ ไม่น้อย</p>\n<p>จากเด็กที่รักกีฬาเป็นทุนเดิม เธอเริ่มต้นเส้นทางนักสู้ด้วยมวยไทย เพราะในเวลานั้น MMA ยังไม่เป็นที่รู้จักในประเทศไทยมากนัก ก่อนก้าวขึ้นมาเป็นนักมวยไทยอาชีพและคว้าแชมป์สภามวยไทยโลก</p>\n<p>“แอมป์เป็นคนที่รักกีฬาเป็นทุนเดิมอยู่แล้ว และรัก MMA มากๆ แต่ตอนนั้นในประเทศไทยยังไม่ได้รับความนิยม ก็เลยเลือกที่จะเล่นมวยไทย พอถึงวันหนึ่งก็ได้เป็นนักมวยไทยอาชีพ ลงแข่งจนได้แชมป์สภามวยไทยโลก”</p>\n<p>ทว่า ความแข็งแกร่งที่พาเธอไปถึงจุดสูงสุดกลับกลายเป็นข้อจำกัด เมื่อแอมป์หาคู่ชกได้ยากในพิกัด 100 ปอนด์ เส้นทางมวยไทยจึงต้องหยุดลง และเธอหันไปเริ่มต้นบทใหม่ในฐานะนักกีฬายูยิตสูทีมชาติไทย</p>\n<p>จากนั้นคือการเดินทางสายใหม่ในระดับนานาชาติ พร้อมความสำเร็จถึงขั้นคว้าแชมป์โลกมาได้ 3 สมัย</p>\n<p>ชื่อของแอมป์มีทั้งแชมป์และเหรียญรางวัล แต่เมื่อมองย้อนกลับไป เธอกลับรู้สึกว่าสิ่งที่ทำมาตลอดคือ ‘หน้าที่’ มากกว่าสิ่งที่หัวใจต้องการ</p>\n<p>เธอเปรียบเทียบชีวิตในช่วงเวลานั้นเหมือนคนที่ต้องนั่งทำงานอยู่หน้าโต๊ะคอมพิวเตอร์ทุกวัน ทั้งที่สิ่งที่อยากทำจริงๆ คือการวาดรูป</p>\n<p>หน้าที่คือสิ่งที่ต้องรับผิดชอบ ส่วนความรักคือสิ่งที่เราอยากทำ และสำหรับแอมป์ สิ่งที่ขาดหายไปคือวันที่สองอย่างนี้จะกลายเป็นเรื่องเดียวกัน</p>\n<p>กระทั่งวันหนึ่ง MMA เริ่มได้รับความนิยมในประเทศไทยมากขึ้น มีการจัดตั้งสมาคมกีฬาอย่างเป็นระบบ และโอกาสที่เคยดูไกลตัวก็เริ่มเดินเข้ามาหาเธอ</p>\n<p>ครั้งนี้แอมป์ไม่ต้องเลือกอีกแล้ว</p>\n<p>เธอได้กลับมาทำในสิ่งที่รัก พร้อมกับทำหน้าที่ในฐานะนักกีฬาไปพร้อมกัน</p>\n<p>“มันคือความกลมกล่อมที่ลงตัวมากๆ เราใช้คำว่าพร้อมถวายชีวิตให้กีฬานี้เลยก็ได้ จากวันที่เริ่มเป็นนักมวยจนมาถึงวันที่ได้เป็นนักกีฬา MMA มันเหมือนเราได้ทำในสิ่งที่เรารักไปพร้อมๆ กับหน้าที่บนสังเวียน ทุกอย่างมันเลยดีไปหมด สามารถหาเลี้ยงตัวเองได้จากสิ่งที่เราชอบจริงๆ”</p>\n<h2>ละทิ้งอีโก้ เพื่อเริ่มต้นใหม่ที่แท้จริง</h2>\n<p>แม้จะได้กลับมาทำในสิ่งที่รัก แต่เส้นทาง MMA กลับไม่ได้เริ่มต้นอย่างสวยงามนัก</p>\n<p>ความสำเร็จจากมวยไทยและยูยิตสูไม่ได้ช่วยให้ทุกอย่างง่ายขึ้น เมื่อก้าวเข้าสู่ MMA อย่างจริงจัง แอมป์พบว่าทั้งรูปแบบการแข่งขัน เวลาการแข่งขัน และวิธีการฝึกซ้อม ล้วนแตกต่างออกไป</p>\n<p>“พอมาเริ่มเล่นจริงๆ จังๆ ก็รู้สึกว่ามันต่างกันเยอะมาก ทั้งรูปแบบการแข่งขัน เวลาการแข่งขัน วิธีการฝึกซ้อม มันคนละเรื่องกันเลย”</p>\n<p>“วันแรกที่กลับมาซ้อมเลยคืออ้วกแตก มันหนักมาก หนักถึงขั้นที่เริ่มตั้งคำถามกับตัวเองว่าหรือว่าเราควรเลิกล้มความตั้งใจนี้ เพราะมันรู้สึกว่าไม่ไหวแล้ว”</p>\n<p>แต่การแข่งขันครั้งแรกกลับกลายเป็นคำตอบ</p>\n<p>แม้ยังไม่พร้อมเต็มร้อยและเหนื่อยจนแทบร้องไห้ แอมป์กลับคว้าเหรียญเงินได้สำเร็จ</p>\n<p>“บอกกับตัวเองว่าขนาดที่เราไม่พร้อมอะไรเลย เรายังได้เหรียญเงินเลย แล้วข้างหน้าโอกาสมันไม่ได้มีแมตช์นี้แมตช์เดียว บวกกับคนรอบตัวคอยให้กำลังใจ ทำให้ลุกขึ้นสู้ต่อ”</p>\n<p>เหรียญเงินครั้งนั้นทำให้แอมป์ตัดสินใจเดินหน้าต่อ แต่สิ่งที่ต้องเปลี่ยนกลับไม่ใช่เพียงร่างกาย หากเป็นตัวตนที่เธอเคยยึดติดมาตลอด</p>\n<p>“เราเป็นถึงระดับแชมป์โลกยูยิตซูนะ แต่ทำไมมาเล่น MMA ถึงทำไม่ได้”</p>\n<p>คำตอบจึงไม่ใช่การพยายามกลับไปเป็นแชมป์โลกคนเดิม แต่คือการยอมทิ้งมันไว้ข้างหลัง</p>\n<p>“ต้องยอมทิ้งอีโก้ทั้งหมดเลย รวมถึงความรู้สึก ทุกๆ อย่าง แล้วมาเริ่มนับหนึ่งใหม่”</p>\n<p>เมื่อไม่ต้องแบกสถานะเดิมขึ้นไปบนสังเวียน แอมป์จึงเปิดพื้นที่ให้ตัวเองเรียนรู้ MMA อย่างแท้จริง จากการเริ่มต้นใหม่ เธอค่อยๆ พัฒนาตัวเอง คว้าเหรียญทองแรก ก่อนก้าวไปถึงตำแหน่งแชมป์โลก MMA ในที่สุด</p>\n<p>บทเรียนครั้งนั้นเปลี่ยนวิธีมองการแข่งขันของเธอไปอย่างสิ้นเชิง</p>\n<p>แอมป์ไม่ได้ขึ้นเวทีด้วยความคิดว่าตัวเองต้องชนะทุกครั้ง แต่ต้องการนำสิ่งที่ฝึกซ้อมมาออกไปแสดงให้ดีที่สุด และเมื่อเลิกกดดันตัวเองว่าต้องชนะทุกครั้ง เธอก็พบว่าคู่ต่อสู้ที่ยากที่สุดอาจไม่ได้อยู่ตรงข้ามบนเวที แต่อยู่ในความคิดของตัวเอง</p>\n<h2>เมื่อชัยชนะไม่ใช่เป้าหมายเดียวของการมีชีวิต</h2>\n<p>จากมวยไทยสู่ยูยิตสู และจากยูยิตสูสู่ MMA เส้นทางของแอมป์ไม่ได้สอนเพียงทักษะการต่อสู้ แต่ค่อยๆ เปลี่ยนวิธีที่เธอมองโลกและมองตัวเองไปพร้อมกัน</p>\n<p>“แอมป์มองว่า MMA มันเหมือนเราต้องอ่านเกมอยู่ตลอดเวลา ไม่มีทางรู้เลยว่าคู่ต่อสู้จะมาในรูปแบบไหน เมื่อสถานการณ์เปลี่ยน นักกีฬาก็ต้องเปลี่ยนตาม ทั้งรุก ทั้งรับ และแก้ไขปัญหาเฉพาะหน้า ทำให้ต้องใช้ความคิดควบคู่ไปกับพละกำลัง”</p>\n<p>“ในชีวิตก็เหมือนกัน จากคนอารมณ์ร้อนกลายมาเป็นคนที่ใจเย็นลงและคิดรอบคอบมากขึ้นก่อนจะลงมือทำอะไร”</p>\n<p>ตลอดเส้นทางที่ผ่านมา แอมป์ต้องเผชิญทั้งคำตัดสิน ความคาดหวัง และภาพจำจากคนรอบข้าง รวมถึงคำถามเกี่ยวกับเพศสภาพที่อยู่กับเธอมาตั้งแต่วัยเด็ก</p>\n<p>สิ่งเหล่านี้อาจเคยเป็นบาดแผล แต่ในอีกมุมหนึ่ง มันก็ทำให้เธอเรียนรู้ว่าอะไรควรเก็บไว้ และอะไรควรวางลง</p>\n<p>MMA จึงกลายเป็นพื้นที่ที่แอมป์ไม่จำเป็นต้องพิสูจน์ตัวเองด้วยคำพูด</p>\n<p>บนสังเวียนไม่มีคำจำกัดความว่าเพศไหนควรแข็งแกร่งกว่าใคร มีเพียงความสามารถ การฝึกฝน และตัวตนที่แต่ละคนเลือกแสดงออกมา</p>\n<p>“ไม่ว่าจะเป็นหญิงหรือชาย ไม่ว่าจะเพศไหน ทุกคนก็มีศักยภาพในตัวเอง”</p>\n<p>จากวันที่เคยมองกีฬาผ่านคำว่า ‘หน้าที่’ มาถึงวันนี้ MMA กลับกลายเป็นพื้นที่ที่ทำให้แอมป์ได้พบทั้งความรัก ความฝัน และตัวตนของตัวเอง</p>\n<p>เมื่อมองย้อนกลับไป การเดินทางของเธอจึงไม่ได้มีเพียงแชมป์หรือเหรียญรางวัล แต่คือการเรียนรู้ที่จะล้ม ยอมรับข้อบกพร่อง กลับมาเริ่มต้นใหม่ และปล่อยวางในสิ่งที่ไม่อาจควบคุม</p>\n<p>เพราะท้ายที่สุดแล้ว การต่อสู้อาจไม่จำเป็นต้องหมายถึงการเอาชนะใคร</p>\n<p>บางครั้งมันอาจเป็นเพียงการได้เป็นตัวเอง ทำในสิ่งที่รัก และเมื่อชีวิตพาให้ล้มลง ก็ยังพร้อมลุกขึ้นสู้อีกครั้ง</p>\n<p>แค่นั้นก็เพียงพอแล้ว</p>\n<h2>คู่แข่งสำคัญ</h2>\n<p>แม้ กัญจุฑา ภัทรบุญซ่อน จะผ่านการคว้าแชมป์โลกและคว้าแชมป์เอเชียมาแล้ว แต่เอเชียนเกมส์ครั้งนี้ถือเป็นอีกบททดสอบ เพราะนอกจากต้องรับมือกับคู่แข่งฝีมือดีแล้ว เธอยังต้องลงแข่งขันท่ามกลางความกดดันของมหกรรมกีฬาระดับทวีป</p>\n<p>หนึ่งในคู่แข่งที่น่าจับตามองคือ Tomoe Katayama จากญี่ปุ่น เจ้าภาพเอเชียนเกมส์ครั้งนี้ ซึ่งนอกจากจะได้เปรียบจากเสียงเชียร์ในบ้านแล้ว ยังเป็นคู่ต่อสู้ที่แอมป์ยอมรับว่าเป็นคนที่เธอหวั่นใจมากที่สุด</p>\n<p>เหตุผลสำคัญคือทั้งคู่ยังไม่เคยเผชิญหน้ากันมาก่อนในทัวร์นาเมนต์ระดับนานาชาติ แม้แอมป์จะเคยศึกษาฝีมือของนักสู้เจ้าภาพผ่านเทปการแข่งขันมาบ้างแล้วก็ตาม</p>\n<p>อีกหนึ่งคู่แข่งที่ประมาทไม่ได้คือ Vallensia Fahira จากอินโดนีเซีย แม้นักสู้สาวไทยจะเคยเอาชนะด้วยการ TKO ในรอบชิงชนะเลิศการแข่งขันซีเกมส์ 2025 เมื่อเดือนธันวาคมที่ผ่านมา แต่การพบกันบนเวทีเอเชียนเกมส์จะประมาทไม่ได้เช่นกัน</p>\n<h2>MMA แข่งที่ไหน ชิงกี่เหรียญทอง</h2>\n<p>MMA หรือ มิกซ์มาเชียลอาร์ต ในเอเชียนเกมส์ ครั้งที่ 20 ชิงชัย 6 เหรียญทอง แข่งขันระหว่างวันที่ 20-22 กันยายน ที่ นาโกย่า ซิตี้ อินาเอะ สปอร์ตเซ็นเตอร์ เขตฮิกาชิ เมืองนาโกย่า จังหวัดไอจิ</p>\n<p>สมาคมกีฬามิกซ์มาเชียลอาร์ตแห่งประเทศไทย ส่งนักกีฬาเข้าร่วม 2 คน ได้แก่ ศักดิ์สิทธิ์ จันทร์หอม รุ่น 71 กิโลกรัมชาย และ กัญจุฑา ภัทรบุญซ่อน รุ่น 54 กิโลกรัมหญิง โดยสมาคมฯ ตั้งเป้าคว้าเหรียญรางวัลจากการแข่งขันครั้งนี้ และทั้งสองคนจะเป็นตัวแทนนักกีฬาไทยที่ลงสนามลุ้นสร้างประวัติศาสตร์ให้กับ MMA ในเอเชียนเกมส์ครั้งแรก</p>","1256538":"<p><a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a> เริ่มต้นการแข่งขันแล้ว และตลอดทัวร์นาเมนต์ยังมีอีกหลายวันที่นักกีฬาไทยเตรียมลงสนามในอีเวนต์สำคัญ พร้อมโอกาสลุ้นเหรียญทองให้ทัพไทย</p>\n<p>THE STANDARD SPORT ชวนปักหมุดวันสำคัญ เช็กกันล่วงหน้าว่าแต่ละวันมีกีฬาอะไร ใครมีโอกาสลงสนาม และวันไหนที่แฟนกีฬาไทยไม่ควรพลาด</p>\n<p>หมายเหตุ: อีเวนต์ที่รวบรวมเป็นการคาดการณ์จากผลงานและเป้าหมายของแต่ละชนิดกีฬา โดยการเข้ารอบและโอกาสลุ้นเหรียญขึ้นอยู่กับผลการแข่งขันจริง</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-1.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 1\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-2.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 2\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-3.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 3\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-4.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 4\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-5.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 5\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-6.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 6\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-7.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 7\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-8.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 8\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-thailand-gold-medal-events-9.jpg\" alt=\"ภาพนักกีฬาไทยหลายคนจากกีฬาต่างๆ ในการแข่งขันเอเชียนเกมส์ 2026 9\" width=\"1080\" height=\"1350\" /></p>","1256456":"<p>วอลเลย์บอลหญิงไทย ชนะคีร์กีซสถาน 3-0 เซ็ต เก็บชัยนัดสองเอเชียนเกมส์ 2026</p>\n<p><a href=\"https://thestandard.co/tag/%E0%B8%A7%E0%B8%AD%E0%B8%A5%E0%B9%80%E0%B8%A5%E0%B8%A2%E0%B9%8C%E0%B8%9A%E0%B8%AD%E0%B8%A5%E0%B8%AB%E0%B8%8D%E0%B8%B4%E0%B8%87%E0%B8%97%E0%B8%B5%E0%B8%A1%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B9%84%E0%B8%97%E0%B8%A2/\" target=\"_blank\" rel=\"noopener\">วอลเลย์บอลหญิงทีมชาติไทย</a>ลงสนามนัดที่สองในศึกเอเชียนเกมส์ 2026 รอบแบ่งกลุ่ม กลุ่ม C พบกับคีร์กีซสถาน</p>\n<p>เกมนี้ทีมสาวไทยทำผลงานได้เหนือกว่าในภาพรวม พร้อมหมุนเวียนผู้เล่นอีกครั้ง พักตัวหลักบางส่วน และเปิดโอกาสให้ผู้เล่นหลายคนได้ลงสัมผัสเกม ก่อนเอาชนะไป 3-0 เซ็ต (25-13, 25-7, 25-7) เก็บชัยชนะเป็นนัดที่สองติดต่อกันในทัวร์นาเมนต์</p>\n<p>สำหรับแมตช์ต่อไป ทีมไทยจะพบกับไชนีสไทเป ในเกมถัดไปของรอบแบ่งกลุ่ม วันพรุ่งนี้ (18 กันยายน) เวลา 17.00 น. ถ่ายทอดสดทาง PPTV HD 36 และ AIS PLAY</p>\n<p><span><strong>ภาพ:</strong><span> ดิษยุตม์ ธนบุญชัย</span></span></p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-1.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 1\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-2.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 2\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-3.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 3\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-4.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 4\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-5.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 5\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-6.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 6\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-7.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 7\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-8.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 8\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-volleyball-beat-kyrgyzstan-asian-games-9.jpg\" alt=\"นักกีฬาวอลเลย์บอลหญิงทีมชาติไทยกำลังแข่งขันกับทีมคีร์กีซสถานในศึกเอเชียนเกมส์ 2026 9\" width=\"850\" height=\"1080\" /></p>","1256119":"<p>เพียงแค่ 10 นาทีแรกของเกมกับไบรท์ตัน ทุกอย่างดูเหมือนกำลังไปได้สวยสำหรับ<a href=\"https://thestandard.co/tag/Manchester-United/\" target=\"_blank\" rel=\"noopener\">แมนเชสเตอร์ ยูไนเต็ด</a></p>\n<p>เช เลซีย์ ประเดิมยิงประตูในการออกสตาร์ทเป็นตัวจริงครั้งแรก ก่อนที่ เมสัน เมาท์ จะบวกเพิ่มให้สกอร์ขยับเป็น 2-0 ในศึกคาราบาวคัพ รอบ 3 ที่โอลด์แทรฟฟอร์ด</p>\n<p>แต่เมื่อสิ้นเสียงนกหวีดยาว 90 นาที สกอร์บนป้ายกลับกลายเป็น 2-3</p>\n<p>แมนฯ ยูไนเต็ด เสีย 3 ประตูรวดจนตกรอบ พร้อมสถิติสุดเจ็บปวด นี่คือครั้งแรกในรอบ 50 ปีที่พวกเขาแพ้เกมในโอลด์แทรฟฟอร์ด ทั้งที่เป็นฝ่ายออกนำก่อน 2-0</p>\n<p>เห็นได้ชัดว่าสิ่งที่น่ากังวลยิ่งกว่าผลแข่งขัน คือรูปเกมหลังผ่านช่วง 20 นาทีแรก</p>\n<p>จากทีมที่เริ่มเกมได้เร็วและมีแนวทางเข้าทำชัดเจน แมนฯ ยูไนเต็ด ค่อยๆ เสียการควบคุมให้ไบรท์ตัน พวกเขาจ่ายบอลพลาดง่ายขึ้น เล่นบอลจากแดนหลังลำบาก และเปิดพื้นที่ให้ทีมเยือนบุกมากดดันหน้าประตูตัวเองบ่อยครั้ง</p>\n<p>ก่อนหมดครึ่งแรก ไบรท์ตันแย่งบอลในพื้นที่สุดท้ายของแมนฯ ยูไนเต็ดได้ถึง 8 ครั้ง มากที่สุดสำหรับทีมเยือนที่มาเล่นในโอลด์แทรฟฟอร์ดในครึ่งแรก นับตั้งแต่ฟูแลมเมื่อเดือนพฤศจิกายน 2022 ขณะที่แมนฯ ยูไนเต็ดจ่ายบอลสำเร็จเพียง 80% ต่ำที่สุดของทีมในฤดูกาลนี้</p>\n<p>หลังจากไบรท์ตันตีไข่แตกก่อนพักครึ่ง เกมก็เริ่มไหลไปทางทีมเยือนอย่างเห็นได้ชัด</p>\n<p>เลนี โยโร กับ เอเดน เฮฟเวน เจองานหนักเมื่อต้องรับมือทั้งการเพรสซิ่งและเกมปะทะของไบรท์ตัน ส่วน ดิโอโก ดาโลต์ และ นุสแซร์ มาซราอุย สองผู้เล่นเก๋าประสบการณ์ กลับไม่ได้ช่วยให้แนวรับนิ่งขึ้นเลย</p>\n<p>ประตูตีเสมอเริ่มจากการเสียบอลในจังหวะที่ไม่ควรเสีย ดาโลต์ เตะบอลขึ้นกลางสนาม เบนจามิน เชชโก ต้องโหม่งย้อนกลับมาท่ามกลางแรงกดดัน ก่อนบอลจะไปเข้าทางผู้เล่นไบรท์ตันในพื้นที่ว่าง</p>\n<p>ส่วนประตู 3-2 ไบรท์ตันเริ่มเล่นจากแดนตัวเอง ใช้การจ่ายบอลเพียง 4 ครั้งก็พาบอลผ่านแนวรับแมนฯ ยูไนเต็ดไปถึง มักซิม เดอ คูเปอร์ สังหารในเขตโทษอย่างง่ายดาย</p>\n<p>ภาพที่เกิดขึ้นทำให้การตัดสินใจในตลาดซื้อขายช่วงซัมเมอร์ถูกหยิบกลับมาพูดถึงอีกครั้ง</p>\n<p>แมนฯ ยูไนเต็ด ทุ่มเงินก้อนใหญ่กับการยกเครื่องแดนกลาง แต่ตลาดกลับปิดลงโดยไม่มี เซ็นเตอร์แบ็ก และ แบ็กซ้าย คนใหม่เข้ามา ทั้งที่เป็นสองตำแหน่งที่ถูกยกเป็นโจทย์ใหญ่มาตลอด</p>\n<p>เคสแบ็กซ้ายเห็นภาพชัดที่สุด สโมสรเคยสอบถามถึง ลูอิส ฮอลล์ แต่ถูกนิวคาสเซิลปฏิเสธ ก่อนจะจบตลาดโดยไร้ตัวเลือกใหม่</p>\n<p>สุดท้ายในเกมกับไบรท์ตัน มาซราอุยต้องรับบทแบ็กซ้าย ดาโลต์ยังอยู่ในช่วงฟอร์มไม่ดี ขณะที่คู่เซ็นเตอร์กลายเป็น โยโร กับ เฮฟเวน สองดาวรุ่งที่ยังขาดชั่วโมงบิน</p>\n<p>แกรี เนวิลล์ เคยเตือนไว้ก่อนตลาดปิดว่า แมนฯ ยูไนเต็ดควรหาเซ็นเตอร์แบ็กและแบ็กซ้ายเพิ่ม เพราะขุมกำลังในแนวรับยังบางเกินไปสำหรับฤดูกาลเต็ม</p>\n<p>เกมกับไบรท์ตันทำให้คำเตือนนั้นกลับมามีน้ำหนักอีกครั้ง</p>\n<p>อย่างไรก็ตาม นักเตะที่อยู่ในสนามก็หนีความรับผิดชอบไม่ได้</p>\n<p>ตลอด 6 เกมแรกของฤดูกาล แมนฯ ยูไนเต็ดมีความผิดพลาดส่วนบุคคลเกิดขึ้นบ่อยครั้ง และเกมนี้ก็เต็มไปด้วยจังหวะเสียบอล การตัดสินใจผิดพลาด และการสื่อสารในแนวรับที่ไม่ลงตัว</p>\n<p>แม้กระทั่งแดนกลางซึ่งเป็นพื้นที่ที่สโมสรลงทุนมากที่สุดในซัมเมอร์ กลับทำหน้าที่ไม่ได้เมื่อโดนไบรท์ตันบีบเพรสซิ่งหนักขึ้น พวกเขาหาทางนำบอลออกจากแดนตัวเองไม่ได้ และไม่มีใครคุมจังหวะเพื่อชะลอความร้อนแรงของเกมหลังทีมนำ 2-0</p>\n<p>ตรงนี้ทำให้คำถามเริ่มมาถึง ไมเคิล คาร์ริก ด้วยเช่นกัน..</p>\n<p>ทีมของเขาถือไพ่เหนือกว่ามากตั้งแต่นาทีแรก แต่หลังจากไบรท์ตันเริ่มตั้งหลักได้ กลับไม่มีการปรับแท็กติกที่ช่วยให้แมนฯ ยูไนเต็ด ดึงการควบคุมกลับมา แม้กระทั่งช่วงท้ายที่ส่ง บรูโน แฟร์นันด์ส และแกนหลักลงสนาม สถานการณ์ก็แทบไม่ดีขึ้น</p>\n<p>คาร์ริกยอมรับหลังเกมว่า ทีมชุดนี้อยู่ในความรับผิดชอบของเขา เมื่อผลงานดีเขาได้รับเครดิต และเมื่อผลการแข่งขันออกมาไม่ดี เขาก็ต้องรับสิ่งที่ตามมาเช่นกัน</p>\n<p>เวลานี้แมนฯ ยูไนเต็ดลงเล่นไป 6 นัดและแพ้ไปแล้ว 3 เกม</p>\n<p>ตัวเลขดังกล่าวต่างจากช่วงแรกของคาร์ริกอย่างชัดเจน เพราะหลังเข้ามารับงานแทน รูเบน อโมริม เมื่อเดือนมกราคม เขาเคยแพ้เพียง 3 จาก 17 นัด ก่อนเริ่มต้นฤดูกาลนี้</p>\n<p>เสียงโห่ดังขึ้นในโอลด์แทรฟฟอร์ดระหว่างครึ่งหลัง และเมื่อจบเกม แฟนบอลจำนวนมากเลือกเดินออกจากสนาม ขณะที่บางส่วนที่ยังอยู่ตะโกนถามคาร์ริกและนักเตะว่าเกิดอะไรขึ้นกับทีม</p>\n<p>คาร์ริก บอกว่าเขาไม่ได้กังวลกับแรงกดดัน สิ่งสำคัญคือการกลับมาชนะเพื่อทำให้ทุกคนรู้สึกว่าทีมกำลังเดินไปข้างหน้า แต่ปัญหาคือช่วงหลายสัปดาห์ที่ผ่านมา แมนฯ ยูไนเต็ด ยังไม่ได้แสดงภาพนั้นออกมาเลย</p>\n<p>ตลาดซัมเมอร์จบไปแล้ว ช่องว่างบางตำแหน่งยังอยู่ นักเตะบางคนกำลังมีปัญหาเรื่องฟอร์ม และทีมที่นำ 2-0 ในบ้านยังไม่สามารถพาตัวเองผ่านเกมที่ควรได้เปรียบไปจนถึงเสียงนกหวีดสุดท้าย</p>\n<p>วันอาทิตย์นี้พวกเขาจะออกไปเยือนฟูแลมในพรีเมียร์ลีก ก่อนเข้าสู่ช่วงพักเบรกทีมชาติ</p>\n<p>แน่นอนว่า 3 คะแนนในเกมนั้นจึงมีความหมายต่อคาร์ริกอย่างยิ่ง</p>\n<p>เพราะหลังคืนที่ปล่อยสกอร์ 2-0 หลุดมือจนกลายเป็น 2-3 สิ่งที่แมนฯ ยูไนเต็ด ต้องการมากที่สุดในเวลานี้ คือชัยชนะเพื่อหยุดวิกฤต ก่อนที่แรงกดดันจะโถมทับหนักไปกว่าเดิม</p>\n<p>.</p>\n<p>และหากทัพปีศาจแดงยังหาชัยชนะไม่เจอในเกมถัดไป คนที่ต้องรับแรงกดดันมากที่สุดคงหนีไม่พ้น ไมเคิล คาร์ริก..</p>\n<p><span><strong>อ้างอิง:</strong></span></p>\n<ul>\n<li><span><a href=\"https://www.bbc.com/sport/football/articles/cmwyzr576y9zo\" target=\"_blank\" rel=\"noopener\">https://www.bbc.com/sport/football/articles/cmwyzr576y9zo</a></span></li>\n<li><span><a href=\"https://www.nytimes.com/athletic/7585620/2026/09/16/manchester-united-carrick-shea-lacey/\" target=\"_blank\" rel=\"noopener\">https://www.nytimes.com/athletic/7585620/2026/09/16/manchester-united-carrick-shea-lacey/</a></span></li>\n<li><span><a href=\"https://www.theguardian.com/football/2026/sep/16/manchester-united-brighton-carabao-cup-third-round-match-report\" target=\"_blank\" rel=\"noopener\">https://www.theguardian.com/football/2026/sep/16/manchester-united-brighton-carabao-cup-third-round-match-report</a></span></li>\n</ul>","1256081":"<p><a href=\"https://thestandard.co/tag/Max-Verstappen/\" target=\"_blank\" rel=\"noopener\">แม็กซ์ เวอร์สแตพเพน</a> นักขับ F1 โชว์ฝีมือหลังพวงมาลัยอีกครั้ง หลังไล่แซงคู่แข่งครบ 100 คน จากการออกสตาร์ทอันดับ 101 ก่อนคว้าชัยในกิจกรรมพิเศษ ‘Max vs 100’ ที่สนามซิลเวอร์สโตน ประเทศอังกฤษ</p>\n<p><a href=\"#photos\" target=\"_blank\" rel=\"noopener\"><img src=\"https://unpkg.com/lucide-static/icons/camera.svg\" alt=\"\" />ดูภาพข่าว</a> </p>\n<p>Max vs 100 เป็นกิจกรรมพิเศษที่นำแม็กซ์กลับมาแข่งขันโกคาร์ต โดยตั้งโจทย์ให้เขาต้องดวลกับคู่แข่งอีก 100 คน ซึ่งประกอบด้วยแฟนมอเตอร์สปอร์ต คอนเทนต์ครีเอเตอร์ นักกีฬา และบุคคลจากหลากหลายวงการ รวมรถบนกริดทั้งหมด 101 คัน</p>\n<p>ความท้าทายสำคัญคือ แม็กซ์ต้องออกสตาร์ทจากอันดับสุดท้าย และมีเวลา 30 รอบ หรือสูงสุด 75 นาที ในการไล่แซงคู่แข่งให้ครบ 100 คน โดยนักแข่งที่ถูกแม็กซ์แซงจะต้องออกจากการแข่งขัน ขณะที่คู่แข่งยังมีทางลัดบนสนามเป็นตัวช่วยเพิ่มระยะห่าง</p>\n<p>อย่างไรก็ตาม แม็กซ์ใช้เวลาไม่นานในการไล่ขึ้นมาด้านหน้า โดยเพียงรอบแรกเขาสามารถผ่านคู่แข่งไปได้ถึง 64 คน ก่อนเข้าสู่กลุ่มท็อป 10 ภายใน 6 รอบ</p>\n<p>ท้ายที่สุด แม็กซ์ใช้เวลาประมาณ 35 นาที และเพียง 14 รอบ ไล่แซงคู่แข่งครบทั้ง 100 คน พร้อมคว้าชัยใน Max vs 100 ได้สำเร็จ จากจุดเริ่มต้นในอันดับ 101 สู่การเป็นรถคันสุดท้ายที่เหลืออยู่บนสนาม</p>\n \n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-1.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 1\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-2.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 2\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-3.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 3\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-4.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 4\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-5.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 5\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-6.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 6\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-7.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 7\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-8.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 8\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-9.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 9\" width=\"850\" height=\"550\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/max-verstappen-max-vs-100-win-10.jpg\" alt=\"แม็กซ์ เวอร์สแตพเพน นักขับ F1 กำลังขับโกคาร์ตในการแข่งขัน Max vs 100 10\" width=\"850\" height=\"550\" /></p>","1256063":"<p>เอเชียนเกมส์ 2026 ทัพไทยมีนักกีฬาหลายคนที่น่าจับตา หลังผ่านทั้งเวทีโอลิมปิก ชิงแชมป์โลก และก้าวขึ้นไปอยู่ในอันดับต้นๆ ของโลกมาแล้ว</p>\n<p>ตั้งแต่ กุลวุฒิ วิทิตศานต์, บัลลังก์ ทับทิมแดง, ภูริพล บุญสอน ไปจนถึงนักกีฬาเทคบอล ยกน้ำหนัก มวยสากล และอีกหลายชนิดกีฬา</p>\n<p>THE STANDARD SPORT ชวนเปิดดีกรีของนักกีฬาไทย ก่อนนำประสบการณ์จากเวทีระดับโลกมาลุยเอเชียนเกมส์ 2026 ที่ประเทศญี่ปุ่น</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-1.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 1\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-2.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 2\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-3.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 3\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-4.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 4\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-5.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 5\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-6.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 6\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-7.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 7\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-8.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 8\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-9.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 9\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-athletes-asian-games-2026-10.jpg\" alt=\"ภาพนักกีฬาไทยระดับโลกหลายคน เตรียมพร้อมสำหรับการแข่งขันเอเชียนเกมส์ 2026 10\" width=\"2250\" height=\"2812\" /></p>","1256034":"<p><a href=\"https://thestandard.co/tag/clear/\" target=\"_blank\" rel=\"noopener\">เคลียร์เลค แคปิตอล</a> เข้าถือครองเชลซีอย่างเต็มรูปแบบ หลัง ท็อดด์ โบห์ลี ประธานสโมสร รวมถึง มาร์ก วอลเตอร์ และ ฮันส์ยอร์ก วิสส์ ตัดสินใจขายหุ้นที่ถืออยู่ให้กับผู้ถือหุ้นใหญ่ของสโมสร</p>\n<p>ก่อนหน้านี้ เคลียร์เลค ซึ่งนำโดย เบห์แดด เอ็กบาลี และ โฮเซ อี. เฟลิเซียโน ถือหุ้นเชลซีอยู่ 61.5% ขณะที่ โบห์ลี, วอลเตอร์ และ วิสส์ ถือหุ้นคนละ 12.8% ก่อนที่ทั้งสามรายจะขายหุ้นทั้งหมด ส่งผลให้เคลียร์เลคเข้าควบคุมสโมสรแบบเต็มตัว</p>\n<p>การเปลี่ยนแปลงครั้งนี้ยังทำให้ โบห์ลี เตรียมลงจากตำแหน่งประธานเชลซี หลังทำหน้าที่มาตั้งแต่ปี 2022 ซึ่งเป็นปีที่กลุ่มทุนเข้าซื้อสโมสรจาก โรมัน อบราโมวิช ด้วยมูลค่า 2.3 พันล้านปอนด์</p>\n<p>โบห์ลี กล่าวว่าการได้ทำหน้าที่ประธานเชลซีถือเป็นเกียรติ พร้อมขอบคุณทุกฝ่ายที่มีส่วนช่วยวางรากฐานอนาคตของสโมสร และเชื่อว่าเชลซีอยู่ในสถานะที่พร้อมเดินหน้าสู่ความสำเร็จต่อไปภายใต้การบริหารของเคลียร์เลค</p>\n<p>ด้าน เอ็กบาลี และ เฟลิเซียโน ขอบคุณโบห์ลีสำหรับช่วงเวลาที่ดำรงตำแหน่งประธาน พร้อมยืนยันว่าจะเดินหน้าลงทุนทั้งด้านโครงสร้างพื้นฐาน ผลงานในสนาม และการพัฒนานักเตะ เพื่อสร้างความสำเร็จระยะยาวให้กับสโมสร</p>\n<p>ขณะที่เชลซีระบุว่า การเปลี่ยนแปลงโครงสร้างผู้ถือหุ้นครั้งนี้จะไม่ส่งผลต่อการดำเนินงานประจำวัน ทีมบริหาร หรือทิศทางของสโมสร</p>","1255923":"<p>เมื่อพูดถึงมหกรรมกีฬาอย่างโอลิมปิกหรือเอเชียนเกมส์ หนึ่งในภาพที่คุ้นเคยคือ ‘หมู่บ้านนักกีฬา’ พื้นที่ซึ่งนักกีฬาจากหลากหลายชาติใช้ชีวิตร่วมกันตลอดการแข่งขัน</p>\n<p>แต่<a href=\"https://thestandard.co/tag/%E0%B9%80%E0%B8%AD%E0%B9%80%E0%B8%8A%E0%B8%B5%E0%B8%A2%E0%B8%99%E0%B9%80%E0%B8%81%E0%B8%A1%E0%B8%AA%E0%B9%8C-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a> ที่ไอจิ-นาโกย่า แตกต่างออกไป เพราะครั้งนี้เจ้าภาพไม่ได้สร้างหมู่บ้านนักกีฬาแบบที่เคยเห็น และเลือกกระจายผู้เข้าร่วมกว่า 17,000 คนไปพักในหลายรูปแบบ</p>\n<p>ตั้งแต่โรงแรม ที่พักชั่วคราว ไปจนถึง ‘เรือสำราญ’ ที่ถูกเปลี่ยนให้กลายเป็นหมู่บ้านนักกีฬาลอยน้ำ</p>\n<p>แล้วทำไมเอเชียนเกมส์ครั้งนี้ถึงไม่มีหมู่บ้านนักกีฬา? นักกีฬาแต่ละส่วนจะพักที่ไหน?</p>\n<p>THE STANDARD SPORT ชวนไปดูเบื้องหลังอีกหนึ่งความแตกต่างของ Aichi-Nagoya 2026</p>\n<p>หมายเหตุ: ข้อมูล ณ 16 กันยายน 2026</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-1.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 1\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-2.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 2\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-3.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 3\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-4.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 4\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-5.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 5\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-6.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 6\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-7.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 7\" width=\"2250\" height=\"2812\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-no-village-athletes-8.jpg\" alt=\"ภาพตู้คอนเทนเนอร์ที่ถูกดัดแปลงเป็นที่พักชั่วคราวสำหรับนักกีฬาเอเชียนเกมส์ 2026 8\" width=\"2250\" height=\"2812\" /></p>\n<p><span><strong>อ้างอิง:</strong></span></p>\n<ul>\n<li><a href=\"https://www.reuters.com/sports/asiad-organisers-pledge-address-accommodation-complaints-cruise-ship-arrives-2026-09-15/?utm_source=chatgpt.com\" target=\"_blank\" rel=\"noopener\">https://www.reuters.com/sports/asiad-organisers-pledge-address-accommodation-complaints-cruise-ship-arrives-2026-09-15/?utm_source=chatgpt.com</a></li>\n<li><a href=\"https://en.sedaily.com/sports/2026/09/14/asian-games-athletes-hit-leaky-container-rooms-days-before?utm_source=chatgpt.com\" target=\"_blank\" rel=\"noopener\">https://en.sedaily.com/sports/2026/09/14/asian-games-athletes-hit-leaky-container-rooms-days-before?utm_source=chatgpt.com</a></li>\n</ul>","1255902":"<p>ฟุตบอลชายทีมชาติไทยลงสนามในศึก<a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a> พบกับคีร์กีซสถาน โดยครึ่งแรกเป็นฝ่ายตามหลัง 0-1 ก่อนช่วงต้นครึ่งหลังจะเสียเพิ่มและถูกทิ้งห่างเป็น 0-2</p>\n<p>อย่างไรก็ตาม ไทยเริ่มต้นการคัมแบ็กในนาที 56 จาก เจะฮานาฟี มามะ ที่โหม่งตีตื้นเป็น 1-2 ก่อนที่ ปริพรรห์ วงษา จะซัดไกลสุดสวยช่วยทีมตีเสมอ 2-2 และอีกเพียง 3 นาทีต่อมา ปริพรรห์ยิงประตูที่สองของตัวเอง พลิกให้ไทยแซงนำ 3-2 ก่อนรักษาสกอร์ไว้ได้จนจบเกม</p>\n<p>สำหรับนัดต่อไป ทีมชาติไทยจะพบกับฮ่องกง วันที่ 20 กันยายน เวลา 14.00 น. ถ่ายทอดสดทางไทยรัฐทีวี และ AIS PLAY</p>","1255897":"<p>สามย่านมิตรทาวน์เปิดพื้นที่ “20th Asian Games Playground @ Samyan Mitrtown” ชวนแฟนกีฬาร่วมเชียร์ทัพนักกีฬาไทยใน<a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a> พร้อมเปิดพื้นที่ให้ทดลองเล่นกีฬาและกิจกรรมต่างๆ ใจกลางเมือง ตั้งแต่วันนี้จนถึงวันที่ 4 ตุลาคม</p>\n<p>ภายในงานมีกิจกรรมให้ร่วมสนุกหลายรูปแบบ ทั้ง Padel Wall-Bounce Challenge, แบดมินตันผ่าน Giant LED, Running Challenge และ Boxing Challenge รวมถึงพื้นที่ Giant LED Screen สำหรับรับชมการถ่ายทอดสดการแข่งขันสำคัญของนักกีฬาไทยไปพร้อมกัน</p>\n<p>กิจกรรมจัดขึ้นภายใต้แคมเปญ “#มากกว่ามหกรรมกีฬา ALL IN ASIAN GAMES” โดยช่วงวันที่ 16-25 กันยายน พบกันที่ลานโปรโมชัน ชั้น G หน้า KFC ก่อนย้ายไปยังชั้น 3 หน้า Celebrity Fitness ระหว่างวันที่ 26 กันยายน – 4 ตุลาคม ตลอดช่วงการแข่งขันเอเชียนเกมส์ 2026</p>","1255793":"<p>Kevin Hart นักแสดงและคอเมเดียนชื่อดังชาวอเมริกัน จับมือ Fabletics เปิดตัวคอลเล็กชันเสื้อผ้ากอล์ฟ หลังเจ้าตัวเริ่มเล่นกีฬาชนิดนี้ได้ไม่ถึงหนึ่งปี และกลายเป็นอีกหนึ่งกิจกรรมที่เขาหลงใหลอย่างจริงจัง</p>\n<p><a href=\"#photos\" target=\"_blank\" rel=\"noopener\"><img src=\"https://unpkg.com/lucide-static/icons/camera.svg\" alt=\"\" />ดูภาพข่าว</a> </p>\n<p><a href=\"https://thestandard.co/tag/kevin-hart/\" target=\"_blank\" rel=\"noopener\">คอลเล็กชัน Kevin Hart x Fabletics</a> มีทั้งหมด 19 ไอเท็มสำหรับทั้งผู้ชายและผู้หญิง ตั้งแต่เสื้อโปโล แจ็กเก็ต กางเกง ไปจนถึงกระโปรงและเลกกิง โดยออกแบบให้สามารถสวมใส่ได้ทั้งในและนอกสนาม พร้อมเปิดตัวโลโก้รูปหัวใจซึ่งเป็นซิกเนเจอร์ใหม่ของ Hart</p>\n<p>โดย Kevin Hart เผยว่า หนึ่งในสิ่งที่ทำให้เขาหลงรักกอล์ฟคือการที่ผู้เล่นสามารถแสดงสไตล์ของตัวเองผ่านการแต่งตัวได้ จึงต้องการนำความคลาสสิกของเสื้อผ้ากอล์ฟมาปรับให้ทันสมัยและใส่ได้ในชีวิตประจำวัน โดยคอลเล็กชันนี้วางจำหน่ายแล้วผ่าน Fabletics ในราคา 29.95-164.95 ดอลลาร์สหรัฐ (ราวๆ 996 – 5,487 บาท)</p>\n \n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/kevin-hart-fabletics-golf-collection-1.jpg\" alt=\"ภาพ Kevin Hart ในชุดเสื้อผ้ากอล์ฟจากคอลเล็กชัน Kevin Hart x Fabletics 1\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/kevin-hart-fabletics-golf-collection-2.jpg\" alt=\"ภาพ Kevin Hart ในชุดเสื้อผ้ากอล์ฟจากคอลเล็กชัน Kevin Hart x Fabletics 2\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/kevin-hart-fabletics-golf-collection-3.jpg\" alt=\"ภาพ Kevin Hart ในชุดเสื้อผ้ากอล์ฟจากคอลเล็กชัน Kevin Hart x Fabletics 3\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/kevin-hart-fabletics-golf-collection-4.jpg\" alt=\"ภาพ Kevin Hart ในชุดเสื้อผ้ากอล์ฟจากคอลเล็กชัน Kevin Hart x Fabletics 4\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/kevin-hart-fabletics-golf-collection-5.jpg\" alt=\"ภาพ Kevin Hart ในชุดเสื้อผ้ากอล์ฟจากคอลเล็กชัน Kevin Hart x Fabletics 5\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/kevin-hart-fabletics-golf-collection-6.jpg\" alt=\"ภาพ Kevin Hart ในชุดเสื้อผ้ากอล์ฟจากคอลเล็กชัน Kevin Hart x Fabletics 6\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/kevin-hart-fabletics-golf-collection-7.jpg\" alt=\"ภาพ Kevin Hart ในชุดเสื้อผ้ากอล์ฟจากคอลเล็กชัน Kevin Hart x Fabletics 7\" width=\"850\" height=\"1080\" /></p>","1255712":"<p>adidas เปิดตัวชุดเหย้าและชุดเยือนใหม่ของทีมชาติโครเอเชียอย่างเป็นทางการ นับเป็นชุดแข่งขันชุดแรกภายใต้ความร่วมมือระยะยาวกับ<a href=\"https://thestandard.co/tag/Croatian-Football-Federation/\" target=\"_blank\" rel=\"noopener\">สหพันธ์ฟุตบอลโครเอเชีย</a> โดยนำองค์ประกอบทางวัฒนธรรมและประวัติศาสตร์ของประเทศมาเป็นหัวใจสำคัญในการออกแบบ</p>\n<p><a href=\"#photos\" target=\"_blank\" rel=\"noopener\"><img src=\"https://unpkg.com/lucide-static/icons/camera.svg\" alt=\"\" />ดูภาพข่าว</a> </p>\n<p>ชุดเหย้ายังคงเอกลักษณ์ตารางหมากรุกสีแดง-ขาวอันโด่งดัง แต่เพิ่มรายละเอียดด้วยตัวอักษรจาก Glagolitic อักษรโบราณที่มีความสำคัญในประวัติศาสตร์โครเอเชีย สอดแทรกลงไปในลวดลาย พร้อมคำว่า ‘Croatia’ ที่เขียนด้วยอักษรดังกล่าวบริเวณใต้คอเสื้อด้านหลัง</p>\n<p>ส่วนชุดเยือนมาในโทนสีน้ำเงินเข้ม โดยได้รับแรงบันดาลใจจากประเพณีการทำลูกไม้ของโครเอเชีย ด้วยกราฟิกลายลูกไม้ที่ปกคลุมทั่วตัวเสื้อ พร้อมคำว่า ‘HRVATSKA’ หรือ ‘โครเอเชีย’ ในภาษาโครเอเชียบริเวณใต้คอเสื้อ ซึ่งออกแบบตัวอักษรให้มีลักษณะคล้ายงานปัก Cross-Stitch</p>\n<p>ทั้งสองชุดมาพร้อมเทคโนโลยี CLIMACOOL+ ของ adidas ใช้วัสดุน้ำหนักเบา เส้น Three Stripes แบบเจาะรู และแผงผ้าตาข่าย เพื่อช่วยเพิ่มการระบายอากาศระหว่างการแข่งขัน ชุดแข่งใหม่นี้ถือเป็นผลงานแรกนับตั้งแต่ adidas และสหพันธ์ฟุตบอลโครเอเชียประกาศความร่วมมือเมื่อต้นปีที่ผ่านมา ซึ่งครอบคลุมทีมชาติโครเอเชียทุกชุด</p>\n<p>โดยทีมชาติชายจะประเดิมสวมชุดใหม่ในการแข่งขันยูฟ่าเนชันส์ลีก ที่กำลังจะมาถึง</p>\n<p>สำหรับ adidas x Croatia ทั้งชุดเหย้าและชุดเยือน เริ่มวางจำหน่ายแล้วผ่าน adidas และร้านค้าที่ร่วมรายการ</p>\n<p><span><strong>ภาพ:</strong><span> adidas</span></span></p>\n \n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-1-1.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 1\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-2.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 2\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-3.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 3\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-4.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 4\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-5.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 5\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-6.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 6\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-7.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 7\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-8.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 8\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-9.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 9\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-10.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 10\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/adidas-croatia-new-jersey-11.jpg\" alt=\"ภาพชุดแข่งทีมชาติโครเอเชียใหม่จาก adidas ที่มีลวดลายอักษรโบราณและงานลูกไม้ 11\" width=\"850\" height=\"1063\" /></p>","1255683":"<p>BMX Racing เป็นกีฬาที่ตัดสินแพ้ชนะกันในเวลาเพียงไม่กี่วินาที ความเร็วบนแทร็ก จังหวะกระโดดข้ามเนิน รวมถึงการเลือกไลน์ในเสี้ยววินาที แต่เบื้องหลังความเร็วเหล่านั้นคือการตัดสินใจ ความกล้า และประสบการณ์ที่หล่อหลอมนักกีฬาแต่ละคนขึ้นมา</p>\n<h2>PLAYER Profile: โกเมธ สุขประเสริฐ</h2>\n \n\n<ul>\n<li><a href=\"#section1\" target=\"_blank\" rel=\"noopener\">โรงเรียนชีวิต เปลี่ยนเด็กธรรมดาสู่แชมป์เอเชีย</a></li>\n<li><a href=\"#section2\" target=\"_blank\" rel=\"noopener\">เสี้ยววินาทีในสนามเปลี่ยนทุกอย่าง</a></li>\n<li><a href=\"#section3\" target=\"_blank\" rel=\"noopener\">จากบทเรียนที่หางโจว สู่ความท้าทายในญี่ปุ่น</a></li>\n<li><a href=\"#section4\" target=\"_blank\" rel=\"noopener\">คู่แข่งสำคัญ</a></li>\n<li><a href=\"#section5\" target=\"_blank\" rel=\"noopener\">จักรยาน แข่งที่ไหน ชิงกี่เหรียญทอง</a></li>\n</ul>\n\n<p> <br />\n </p>\n<p>สำหรับ ส.ท.โกเมธ สุขประเสริฐ นักปั่น BMX Racing มือหนึ่งของไทย สิ่งที่พาเขามาถึงตำแหน่งแชมป์เอเชีย 3 สมัย จึงไม่ใช่เพียงกล้ามเนื้อหรือพรสวรรค์ หากแต่เป็นวิธีคิดที่ถูกขัดเกลาจากสนามแข่งและชีวิตจริง</p>\n<p>THE STANDARD SPORT ชวนพูดคุยกับโกเมธถึงอีกด้านของชีวิตนักกีฬา เมื่อ BMX ไม่ได้สอนเพียงวิธีเอาชนะคู่แข่ง แต่สอนให้เขารู้จักคิด ตัดสินใจ ล้ม และลุกขึ้นมาใหม่ เพื่อเป้าหมายที่ใหญ่กว่าเหรียญรางวัล นั่นคือการสร้างชีวิตที่ดีให้ครอบครัว</p>\n<h2>โรงเรียนชีวิต เปลี่ยนเด็กธรรมดาสู่แชมป์เอเชีย</h2>\n<p>จุดเริ่มต้นของโกเมธไม่ได้มีอะไรหวือหวา เขาเป็นเพียงเด็กต่างจังหวัดที่ชื่นชอบกีฬาความเร็ว ก่อนจะถูกอาจารย์แถวบ้านชักชวนให้ลองปั่น BMX และไม่นานก็ตกหลุมรักกีฬาชนิดนี้อย่างเต็มตัว</p>\n<p>“ก่อนหน้านี้ผมเตะฟุตบอลมาก่อน แต่ BMX มันมาจากเห็นพี่ชายขี่มอเตอร์ไซค์วิบาก ก็เลยรู้สึกว่ามันท้าทายดี แล้วก็ชอบความเร็วอยู่แล้ว เลยอยากลอง”</p>\n<p>จากเด็กที่เริ่มต้นด้วยความชอบ BMX ค่อยๆ กลายเป็นเส้นทางชีวิต เมื่อคุณพ่อพาไปลงแข่งขันชิงแชมป์ประเทศไทย ก่อนที่ความฝันจะขยับใหญ่ขึ้นเมื่อเขาได้เห็น อะแมนด้า คาร์ รุ่นพี่นักปั่นหญิงไทยคว้าสิทธิ์ไปแข่งโอลิมปิกเกมส์ 2016</p>\n<p>ภาพนั้นกลายเป็นแรงผลักดันให้โกเมธมีความหวัง เพราะหากรุ่นพี่ทำได้ ตัวเขาเองก็อยากไปให้ถึงจุดนั้นเช่นกัน</p>\n<p>จุดเปลี่ยนครั้งสำคัญเกิดขึ้นเมื่อโกเมธถูกส่งไปเก็บตัวฝึกซ้อมที่ศูนย์ฝึกจักรยานโลก (WCC) ประเทศสวิตเซอร์แลนด์ ตั้งแต่อายุเพียง 17 ปี</p>\n<p>การใช้ชีวิตคนเดียวในต่างแดน โดยที่พูดภาษาไม่ได้ และต้องจัดการทุกอย่างด้วยตัวเอง อาจเป็นเรื่องยากสำหรับวัยรุ่นคนหนึ่ง แต่สำหรับโกเมธ นั่นคืออีกสนามหนึ่งที่สำคัญไม่แพ้แทร็ก BMX</p>\n<p>“ผมไปอยู่สวิตเซอร์แลนด์ตั้งแต่อายุ 17 เพิ่งกลับไทยตอนปีโอลิมปิก ทักษะการขี่ของผมมาจากที่นั่นหมดเลย เขาฝึกให้ทุกอย่าง ทั้งการคิดและการตัดสินใจ ไปคนเดียว ภาษาไม่ได้ ต้องเอาตัวรอดเอง จัดการเองทั้งหมด มันเลยเอามาใช้ได้ทั้งในสนามและการใช้ชีวิตทุกวันนี้ในการแก้ปัญหา”</p>\n<p>ตลอด 7 ปีในยุโรป โกเมธไม่ได้เรียนรู้เพียงเรื่องเทคนิคการปั่น แต่ยังเรียนรู้วิธีคิด การปรับตัว และ การรับมือกับสถานการณ์ที่คาดเดาไม่ได้</p>\n<p>ทั้งหมดกลายเป็นรากฐานสำคัญที่พาเขาก้าวขึ้นมาเป็นหนึ่งในนักปั่น BMX ที่ดีที่สุดของทวีป หลังคว้าแชมป์เอเชีย 3 สมัยติดต่อกัน (2022-24) และ สร้างประวัติศาสตร์เป็นนักปั่น BMX ชายไทยคนแรกที่คว้าตั๋วโอลิมปิกเกมส์ 2024 ที่กรุงปารีส</p>\n<h2>เสี้ยววินาทีในสนามเปลี่ยนทุกอย่าง</h2>\n<p>หากชีวิตเปรียบเหมือนแทร็ก BMX ที่ต้องเร่งความเร็ว เบียดแย่งไลน์ และตัดสินใจภายในเสี้ยววินาที โกเมธเลือกที่จะแยกโลกสองใบออกจากกันอย่างชัดเจน</p>\n<p>นอกสนาม เขาคือคนเรียบง่าย สบายๆ ใช้ชีวิตแบบคนธรรมดา แต่ทันทีที่ก้าวเข้าสู่สนามแข่ง สัญชาตญาณของนักกีฬาจะถูกเปิดขึ้นทันที</p>\n<p>“ส่วนตัวผมในสนามกับนอกสนามค่อนข้างแตกต่างกันชัดเจน นอกสนามผมจะเป็นคนสบายๆ แต่เวลาจะทำอะไรต้องคิดให้รอบคอบก่อนเสมอ แต่ในสนามจะเป็นอีกโหมดหนึ่งเลย เพราะในโหมดการแข่งขัน ทุกอย่างมันเปลี่ยน BMX เป็นเกมที่เร็วมาก ทุกอย่างอยู่ที่จังหวะและโอกาส ถ้าเราตัดสินใจพลาดก็คือพลาด แต่ถ้าขี่ไม่มีความเร็วเลยก็ไม่ดี”</p>\n<p>คำว่า “ตัดสินใจ” จึงเป็นหนึ่งในหัวใจสำคัญของ BMX เพราะต่อให้มีความเร็วมากแค่ไหน หากเลือกไลน์ผิดเพียงครั้งเดียว ทุกอย่างก็สามารถเปลี่ยนได้ในพริบตา</p>\n<p>แนวคิดเดียวกันนี้ถูกนำมาใช้ในชีวิตของโกเมธ โดยเฉพาะในช่วงเวลาที่ต้องเผชิญกับอุปสรรคใหญ่ที่สุดอย่างอาการบาดเจ็บ ทั้งกระดูกแขนหักสองข้างและกล้ามเนื้อสะโพกฉีก</p>\n<p>ในวันที่นักกีฬาคนหนึ่งไม่รู้ว่าจะกลับมาขี่ได้เหมือนเดิมหรือไม่ สิ่งที่ทำให้โกเมธลุกขึ้นมาเริ่มต้นใหม่กลับไม่ใช่เรื่องของการแข่งขัน แต่เป็นภาพของคนสองคนที่อยู่เบื้องหลังทุกความสำเร็จของเขาคือพ่อและแม่</p>\n<p>“พอเราล้ม ทุกคนก็ท้ออยู่แล้ว กลัวว่าจะกลับมาขี่เหมือนเดิมได้ไหม แต่พอเราเดินมาไกลมากแล้ว และพ่อแม่อายุขนาดนี้เขายังขยันสู้เลย พอมองพ่อกับแม่แล้ว รู้สึกว่าเราท้อไม่ได้ ต้องรีบลุกขึ้นมาสู้ เวลาท้อผมจะคิดถึงพ่อกับแม่ พวกท่านสู้ทุกวัน เราล้มแค่นี้เอง ก็ต้องลุกกลับมาสู้”</p>\n<h2>จากบทเรียนที่หางโจว สู่ความท้าทายในญี่ปุ่น</h2>\n<p>เอเชียนเกมส์ ครั้งที่ 19 ที่หางโจว คือหนึ่งในบทเรียนสำคัญของโกเมธ</p>\n<p>เวลานั้นเขาลงแข่งขันในฐานะ “มือ 1 เอเชีย” หลังเพิ่งคว้าตั๋วโอลิมปิกมาหมาดๆ ชื่อเสียง ผลงาน และความคาดหวังที่ถาโถมเข้ามา กลายเป็นแรงกดดันที่เขาต้องเรียนรู้ว่าจะจัดการอย่างไร</p>\n<p>สุดท้ายโกเมธคว้าเหรียญเงินกลับบ้าน แต่สิ่งที่ติดตัวกลับมาด้วยไม่ใช่เพียงเหรียญรางวัล หากเป็นบทเรียนที่ช่วยให้เขามองการแข่งขันครั้งต่อไปแตกต่างออกไป</p>\n<p>เมื่อเข้าสู่เอเชียนเกมส์ 2026 ที่ประเทศญี่ปุ่น โกเมธจึงไม่ได้แบกความคาดหวังแบบเดิมอีกแล้ว</p>\n<p>“เอเชียนเกมส์รอบที่แล้วผมเป็นมือ 1 เอเชีย มันก็เลยมีความกดดันพอสมควร แต่ปีนี้แข่งที่ญี่ปุ่น แม้สนามจะใช้เทคนิคเยอะและเจ้าภาพอาจได้เปรียบ แต่ถามว่ากดดันแค่ไหน มันไม่ได้กดดันขนาดนั้น เพราะเราแข่งในบ้านเขา มันเหมือนไม่มีอะไรจะเสีย เราก็แค่ขี่ให้ดีที่สุด ไม่ได้กดดันตัวเองเท่ารอบที่แล้ว”</p>\n<p>สนามที่ญี่ปุ่นอาจเป็นความท้าทาย โดยเฉพาะเมื่อเจ้าภาพมีความคุ้นเคยกับแทร็กมากกว่า แต่โกเมธเลือกที่จะรับมือด้วยการเตรียมตัวล่วงหน้า เขาบินไปญี่ปุ่นเพื่อศึกษาสนาม เก็บภาพรายละเอียดกลับมาวิเคราะห์ และนำข้อมูลเหล่านั้นมาปรับการฝึกซ้อมที่ประเทศไทย</p>\n<p>ครั้งนี้เขาจึงไม่ได้ลงสนามเพียงเพื่อทำหน้าที่ในฐานะนักกีฬาทีมชาติ แต่ต้องการรู้ว่าตัวเองจะไปได้ไกลแค่ไหน หากทุ่มทุกอย่างที่มีลงไปในการแข่งขัน</p>\n<p>เพราะท้ายที่สุด สิ่งที่โกเมธอยากทิ้งไว้จากการเป็นนักกีฬาทีมชาติ อาจไม่ใช่จำนวนเหรียญรางวัลที่สะสมได้ หากเป็นผลงานที่ทำให้คนรุ่นหลังจดจำ และเป็นความภาคภูมิใจของครอบครัว</p>\n<p>“ตอนคัดเลือกโอลิมปิกได้ มันเป็นตั๋วใบแรกของประเทศไทยตอนนั้นด้วย พ่อแม่ก็ดีใจ เป็นเกียรติแก่วงศ์ตระกูล นอกสนามผมก็เป็นคนปกติทั่วไป แต่อยากให้แฟนกีฬาจดจำผมในฐานะนักกีฬาที่ฝากผลงานที่น่าจดจำมากกว่า”</p>\n<p>เมื่อเสียงสัญญาณปล่อยตัวดังขึ้นในการแข่งขันเอเชียนเกมส์ 2026 โกเมธอาจมีเวลาเพียงไม่กี่วินาทีในการตัดสินใจว่าจะเร่งเครื่อง เบียดแย่งไลน์ หรือเลือกจังหวะเพื่อพาตัวเองไปถึงเส้นชัย</p>\n<p>แต่ไม่ว่าจะจบการแข่งขันด้วยผลลัพธ์แบบไหน สิ่งหนึ่งที่ไม่เคยเปลี่ยนคือหัวใจของเด็กคนเดิมที่เคยหลงใหลในความเร็ว</p>\n<p>เด็กคนหนึ่งที่เติบโตขึ้นจาก BMX เรียนรู้การใช้ชีวิตจากต่างแดน ล้มแล้วลุกจากอาการบาดเจ็บ และยังคงกดสปีดต่อไปด้วยเหตุผลที่มากกว่าการเอาชนะคู่แข่ง</p>\n<p>เพื่อครอบครัว เพื่อธงชาติไทย และเพื่อพิสูจน์ขีดจำกัดของตัวเอง</p>\n<p>“BMX และชีวิต มันคล้ายๆ กัน ในเกมการแข่งขันเราต้องต่อสู้เพื่อที่จะชนะคู่แข่ง ชีวิตเราก็ต้องสู้เหมือนกัน ต้องฝ่าฟันให้ผ่านอุปสรรคต่างๆ เพื่อที่จะให้ชีวิตเรามีอนาคตที่ดี”</p>\n<h2>คู่แข่งสำคัญ</h2>\n<p>เอเชียนเกมส์ ครั้งที่ 20 โกเมธคือหนึ่งในความหวังเหรียญทองของทีมจักรยานไทย แต่เส้นทางสู่ตำแหน่งแชมป์ไม่มีคำว่าง่าย เมื่อมีคู่แข่งสำคัญจาก 2 ชาติที่พร้อมท้าทายเขา</p>\n<p>โดยเฉพาะเจ้าภาพอย่างญี่ปุ่น ตัวเต็งนำโดย อาซูมะ นากาอิ เจ้าของเหรียญทองเอเชียนเกมส์ ครั้งที่ 19 และแชมป์เอเชีย 2 ปีติดต่อกัน (2025-26) รวมถึง เรียว ชิมาดะ เจ้าของเหรียญทองแดงชิงแชมป์เอเชีย 2026 ทั้งสองคนถือเป็นคู่แข่งที่โกเมธต้องจับตาเป็นพิเศษ นอกจากฟอร์มการปั่นที่แข็งแกร่งแล้ว ยังมีข้อได้เปรียบจากการคุ้นเคยกับสนาม รวมถึงเสียงเชียร์ของแฟนกีฬาในฐานะเจ้าภาพ</p>\n<p>อีกหนึ่งคู่ปรับสำคัญคือ แพทริค เบรน คู จากฟิลิปปินส์ ซึ่งเคยดวลกับโกเมธมาแล้วหลายครั้ง แม้จะเป็นฝ่ายพ่ายแพ้ให้กับนักปั่นไทยในซีเกมส์ ครั้งที่ 33 แต่ก็กลับมาทำผลงานได้อย่างโดดเด่นในศึกชิงแชมป์เอเชีย 2026 ด้วยการคว้าเหรียญเงิน</p>\n<p>ทั้งสามคนต่างเป็นคู่แข่งที่โกเมธเคยเผชิญหน้ามาแล้ว และเขามองว่าจุดเด่นของแต่ละคนอยู่ที่ความแข็งแรง ความเร็ว และพละกำลังที่ดี แต่ยังเชื่อมั่นว่าตัวเองมีดีพอที่จะเอาชนะและคว้าเหรียญทองมาครอง</p>\n<h2>จักรยาน แข่งที่ไหน ชิงกี่เหรียญทอง</h2>\n<p>จักรยานในเอเชียนเกมส์ ครั้งที่ 20 ชิงชัยรวม 22 เหรียญทอง แบ่งเป็นจักรยานถนน 4 เหรียญทอง จักรยานประเภทลู่ 12 เหรียญทอง BMX 4 เหรียญทอง และจักรยานเสือภูเขา 2 เหรียญทอง โดยแข่งขันระหว่างวันที่ 20 กันยายน – 2 ตุลาคม</p>\n<p><a href=\"https://thestandard.co/tag/%E0%B8%AA%E0%B8%A1%E0%B8%B2%E0%B8%84%E0%B8%A1%E0%B8%81%E0%B8%B5%E0%B8%AC%E0%B8%B2%E0%B8%88%E0%B8%B1%E0%B8%81%E0%B8%A3%E0%B8%A2%E0%B8%B2%E0%B8%99%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B9%80%E0%B8%97%E0%B8%A8%E0%B9%84%E0%B8%97%E0%B8%A2/\" target=\"_blank\" rel=\"noopener\">สมาคมกีฬาจักรยานแห่งประเทศไทย</a>ส่งนักกีฬาเข้าร่วมการแข่งขัน 22 คน นำโดยนักกีฬาความหวังในแต่ละประเภทอย่าง โกเมธ สุขประเสริฐ รองแชมป์เก่าในประเภท BMX, อาทิตย์ ปูลาร์ด ลูกครึ่งไทย-ฝรั่งเศส ในประเภทถนน และ จาย อังค์สุธาสาวิทย์ ในประเภทลู่</p>\n<p>สำหรับเป้าหมายของทีมจักรยานไทย สมาคมฯ ตั้งความหวังเบื้องต้นไว้ที่การคว้าเหรียญรางวัลกลับบ้านอย่างน้อย 1 เหรียญ ขณะเดียวกันยังเชื่อว่าทีมมีโอกาสลุ้นถึงเหรียญทองได้เช่นกัน</p>\n<p>.</p>","1255663":"<p>การถอนตัวจากเอเชียนเกมส์ 2026 ของ <a href=\"https://thestandard.co/tag/%E0%B8%A3%E0%B8%A7%E0%B8%87%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7-%E0%B8%A5%E0%B8%B1%E0%B8%A5%E0%B8%99%E0%B8%B2-%E0%B8%98%E0%B8%B2%E0%B8%A3%E0%B8%B2%E0%B8%A4%E0%B8%94%E0%B8%B5/\" target=\"_blank\" rel=\"noopener\">รวงข้าว-ลัลนา ธาราฤดี</a> อาจสร้างความรู้สึกเสียดาย เพราะนี่คือช่วงเวลาที่นักเทนนิสหญิงมือ 1 ของไทยกำลังเล่นเทนนิสได้ดีที่สุดช่วงหนึ่งในชีวิต</p>\n<h2>ประเด็นสำคัญ</h2>\n \n\n<ul>\n<li><a href=\"#section1\" target=\"_blank\" rel=\"noopener\">รวงข้าวถอนตัว เพราะกำลังเลือกเส้นทางของตัวเอง</a></li>\n<li><a href=\"#section2\" target=\"_blank\" rel=\"noopener\">ปฏิทินการแข่งขันของนักเทนนิสไม่เหมือนกีฬาหลายชนิด</a></li>\n<li><a href=\"#section3\" target=\"_blank\" rel=\"noopener\">รวงข้าวไม่ใช่คนเดียวที่ต้องตัดสินใจแบบนี้</a></li>\n<li><a href=\"#section4\" target=\"_blank\" rel=\"noopener\">สิ่งสำคัญคือสมาคมเลือก ‘เข้าใจ’ มากกว่า ‘ขัดแย้ง’</a></li>\n<li><a href=\"#section5\" target=\"_blank\" rel=\"noopener\">เพราะเป้าหมายปลายทางคือโอลิมปิกเกมส์</a></li>\n<li><a href=\"#section6\" target=\"_blank\" rel=\"noopener\">คำถามจึงไม่ควรเป็นว่า ‘ทำไมไม่เล่นเอเชียนเกมส์?’</a></li>\n</ul>\n\n<p> <br />\n </p>\n<p>อันดับโลกของเธอขยับขึ้นมาถึงมือ 61 โลก และอยู่ห่างจากเป้าหมายระดับท็อป 50 ไม่มาก แต่หากมองให้ลึกกว่าคำว่า ‘ถอนตัวทีมชาติ การตัดสินใจครั้งนี้สะท้อนโจทย์ที่ซับซ้อนกว่านั้น</p>\n<p>เพราะสำหรับนักเทนนิสอาชีพ เอเชียนเกมส์ไม่ได้เกิดขึ้นในปฏิทินการแข่งขันที่ว่างเปล่า ทุกสัปดาห์ที่เลือกแข่งขันรายการหนึ่ง จึงหมายถึงการต้องยอมปล่อยอีกรายการหนึ่งไปพร้อมกัน</p>\n<h2>รวงข้าวถอนตัว เพราะกำลังเลือกเส้นทางของตัวเอง</h2>\n<p>วันที่ 14 กันยายน ลัลนายื่นหนังสือขอถอนตัวต่อสมาคมกีฬาลอนเทนนิสแห่งประเทศไทยฯ โดยให้เหตุผลว่า หลังปรึกษาทีมงานและผู้จัดการส่วนตัวแล้ว เธอต้องการปรับแผนการแข่งขันเพื่อพัฒนาผลงานและอันดับโลก</p>\n<p>เป้าหมายระยะใกล้คือการขยับจากอันดับ 61 เข้าสู่ท็อป 50 เพื่อเพิ่มโอกาสเข้าแข่งขันรายการสำคัญในปีต่อไป</p>\n<p>แต่เป้าหมายที่ใหญ่กว่านั้นคือการไปลุยโอลิมปิก ลอสแองเจลิส 2028</p>\n<p>นั่นทำให้การถอนตัวครั้งนี้ไม่ได้หมายถึงการลดความสำคัญของทีมชาติ หากเป็นการเลือกเส้นทางอีกแบบ เพื่อหวังกลับไปแข่งขันในนามประเทศไทยบนเวทีที่ใหญ่กว่าเดิม</p>\n<p>ความแตกต่างระหว่างอันดับ 61 กับท็อป 50 อาจดูไม่มาก แต่ในโลกเทนนิสอาชีพ อันดับสามารถเปลี่ยนเส้นทางอาชีพของนักกีฬาได้</p>\n<p>อันดับโลกมีผลตั้งแต่การเข้าสู่รอบเมนดรอว์รายการใหญ่ ไปจนถึงโอกาสเลือกรายการที่เหมาะกับการสะสมคะแนนที่มากขึ้น</p>\n<p>เมื่อขึ้นไปถึงระดับหนึ่ง นักกีฬาจะไม่ต้องเสียพลังงานไปกับรอบคัดเลือกมากเท่าเดิม และสามารถวางโปรแกรมการแข่งขันได้มีประสิทธิภาพกว่าเดิม</p>\n<p>ดังนั้นช่วงเวลาที่รวงข้าวกำลังเข้าใกล้ท็อป 50 จึงมีความสำคัญมาก และปฏิเสธไม่ได้ว่าโมเมนตัมที่กำลังเกิดขึ้นอาจเป็นสิ่งที่ทีมของเธอไม่ต้องการให้มันหยุดลง</p>\n<h2>ปฏิทินการแข่งขันของนักเทนนิสไม่เหมือนกีฬาหลายชนิด</h2>\n<p>บริบทสำคัญที่ทำให้การตัดสินใจของรวงข้าวต้องถูกมองต่างจากกีฬาที่มีการแข่งขันทีมชาติเป็นแกนกลาง เพราะนักเทนนิสใช้ชีวิตอยู่กับทัวร์แทบตลอดทั้งปี และต้องบริหารทั้งคะแนนสะสม เงินรางวัล การเดินทาง สภาพร่างกาย รวมไปถึงช่วงเวลาที่กำลังอยู่ในฟอร์มที่พีก</p>\n<p>ปัญหาใหญ่คือ เทนนิสเอเชียนเกมส์ไม่มีคะแนนรองรับ ทำให้ไม่มีผลต่อการทำอันดับโลก ตรงกันข้ามในช่วงเวลาเดียวกันบนปฏิทินการแข่งขัน WTA มีรายการระดับ 1000 อย่าง ไชน่าโอเพน รออยู่</p>\n<p>การไม่ไปแข่งขันในรายการที่มีวางอันดับที่กำหนดต้องไปแข่งขัน นอกจากจะโดนปรับเงินจำนวนหนึ่งแล้ว ที่เสียหายหนักคือการพลาดโอกาสสำคัญในการทำคะแนนเพิ่ม ซึ่งคะแนนที่ว่าคือระดับ 1000 คะแนน หากเกิดได้แชมป์ขึ้นมาก็สามารถขยับอันดับรวงข้าวได้มากกว่า 20 อันดับ หากเกิดว่าเธอไปถึงจุดนั้นได้จริง</p>\n<p>ขณะที่เอเชียนเกมส์ถือเป็นอีกทัวร์นาเมนต์หนึ่งที่ถูกวางไว้ทับกับการแข่งขันในทัวร์นาเมนต์ของ WTA และเมื่อการแข่งขันเทนนิสที่ญี่ปุ่นมีขึ้นระหว่างวันที่ 27 กันยายน-3 ตุลาคม การเดินทางมาเล่นย่อมหมายถึงการปรับแผนส่วนอื่นตามไปด้วย</p>\n<h2>รวงข้าวไม่ใช่คนเดียวที่ต้องตัดสินใจแบบนี้</h2>\n<p>ภาพดังกล่าวชัดขึ้นเมื่อเอเชียนเกมส์ครั้งนี้ไม่ได้มีนักเทนนิสเอเชียระดับโลกทุกคนเข้าร่วม อาทิ นาโอมิ โอซากะของญี่ปุ่น หรือ เอเลนา รีบาคินาของคาซัคสถาน ก็ไม่ได้อยู่บนเส้นทางสู่การแข่งขันครั้งนี้เช่นกัน</p>\n<p>บริบทและเหตุผลของแต่ละคนอาจแตกต่างกัน จึงไม่ควรนำมาเทียบกันแบบตรงไปตรงมา แต่สิ่งหนึ่งที่กรณีเหล่านี้สะท้อนร่วมกันคือ สำหรับนักเทนนิสระดับอาชีพ การรับใช้ทีมชาติและการบริหารทัวร์นาเมนต์ที่ลงไม่สามารถแยกออกจากปฏิทินของ WTA ได้</p>\n<p>บางครั้งการเลือกไม่เล่นรายการหนึ่ง จึงไม่ได้หมายความว่ารายการนั้นไม่มีความสำคัญ แต่หมายถึงมีเป้าหมายอื่นที่ต้องให้ความสำคัญมากกว่าในช่วงเวลานั้น</p>\n<p>หากมองจากมุมของเอเชียนเกมส์ การไม่มีรวงข้าวย่อมเป็นความเสียหายของทีมไทยอย่างหลีกเลี่ยงไม่ได้ เพราะมือวาง 61 ของโลกคือหนึ่งในนักกีฬาที่มีศักยภาพสูงที่สุดของทีม และการไม่มีเธอทำให้โอกาสในประเภทหญิงลดลง</p>\n<p>แต่หากมองจากเส้นทางอาชีพของนักกีฬา สมการอาจแตกต่างออกไป เพราะความสำเร็จของเทนนิสไม่สามารถวัดด้วยจำนวนเหรียญจากมหกรรมกีฬาเพียงอย่างเดียว</p>\n<p>การมีนักเทนนิสไทยขึ้นไปยืนในระดับท็อป 50, เข้าแข่งขันระดับแกรนด์สแลมอย่างต่อเนื่อง หรือไปถึงโอลิมปิกเกมส์ ก็สามารถเป็นความสำเร็จของวงการเทนนิสไทยได้เช่นเดียวกัน</p>\n<p>สิ่งที่ทำให้เรื่องนี้น่าสนใจยิ่งขึ้นคืออเล็กซ์ เอียลา มือ 18 โลกจากฟิลิปปินส์ ซึ่งเลือกตรงกันข้าม เธอยืนยันจะเล่นเอเชียนเกมส์ แม้การแข่งขันทับกับไชน่าโอเพน</p>\n<p>สำหรับผู้เล่นอันดับระดับเธอ หาก WTA ไม่อนุมัติข้อยกเว้นเอียลา อาจถูกปรับ 10,000 ดอลลาร์ และถูกปรับคะแนนซึ่งกระทบอันดับโลกโดยตรง</p>\n<p>กรณีนี้จึงไม่มีคำตอบว่าใคร “เลือกถูกกว่า” แต่สะท้อนความจริงเดียวกันว่า นักเทนนิสแต่ละคนต้องกำหนดว่าอะไรสำคัญที่สุดต่ออาชีพของตัวเองในช่วงเวลานั้น</p>\n<h2>สิ่งสำคัญคือสมาคมเลือก ‘เข้าใจ’ มากกว่า ‘ขัดแย้ง’</h2>\n<p>อีกด้านที่น่าสนใจของเรื่องนี้คือท่าทีจากสมาคมกีฬาลอนเทนนิสแห่งประเทศไทยฯ โดยทางสุชัย พรชัยศักดิ์อุดม นายกสมาคมฯ ยืนยันว่าเข้าใจการตัดสินใจ พร้อมสนับสนุนเป้าหมายในการไปโอลิมปิกเกมส์ของลัลนา</p>\n<p>โอลิมปิกเกมส์จะมีนักเทนนิสประเภทเดี่ยว 64 คนเข้าร่วม และ 56 จาก 64 คนนั้น มาจากการเป็นมืออันดับโลกที่สูงที่สุด โดยแต่ละชาติจะได้โควตานี้ไม่เกิน 4 คน</p>\n<p>นั่นหมายความว่า หากตัดอันดับเอาโควตาในวันนี้ อันดับ 61 ของลัลนาอาจจะยังไม่เพียงพอ แต่หากเธอทำอันดับได้ท็อป 50 อย่างที่หวัง ก็แทบจะการันตีในการไปโอลิมปิกแบบ 100%</p>\n<p>นี่เป็นรายละเอียดที่สำคัญ เพราะแทนที่จะทำให้เรื่องกลายเป็นความขัดแย้งระหว่าง “ทีมชาติ” กับ “นักกีฬาอาชีพ” ทั้งสมาคมและนักเทนนิสกลับมองเห็นเป้าหมายร่วมกัน รวงข้าวเองก็ยืนยันในหนังสือว่าจะกลับมาแข่งขันให้ทีมชาติไทยในอนาคต</p>\n<p>ดังนั้นสิ่งที่เกิดขึ้นจึงไม่ใช่การปิดประตูทีมชาติ แต่เป็นการจัดลำดับความสำคัญในช่วงหนึ่งของอาชีพนักเทนนิส</p>\n<h2>เพราะเป้าหมายปลายทางคือโอลิมปิกเกมส์</h2>\n<p>ประเทศไทยเคยมีนักเทนนิสไปแข่งขันในโอลิมปิกเกมส์ ทั้ง ภราดร ศรีชาพันธุ์, แทมมารีน ธนสุกาญจน์, เบญจมาศ แสงอร่าม, สุวิมล ดวงจันทร์ รวมถึง สนฉัตร และสรรค์ชัย รติวัฒน์</p>\n<p>แต่ภาพของนักเทนนิสไทยบนเวทีโอลิมปิกห่างหายไปเป็นเวลานาน สำหรับรวงข้าว การขึ้นท็อป 50 จึงไม่ใช่เส้นชัยสุดท้าย แต่เป็นอีกขั้นของการสร้างทำอันดีบโลกและสถานะบนทัวร์เพื่อเพิ่มโอกาสไปถึงเป้าหมายในอีกสองปีข้างหน้า</p>\n<p>เอเชียนเกมส์จึงเป็นสิ่งที่เธอต้องยอมแลกในระยะสั้น เพื่อรักษาเส้นทางระยะยาวนั้นเอาไว้</p>\n<p>นอกจากนี้การถอนตัวของรวงข้าวไม่ได้หมายความว่าความหวังของเทนนิสไทยในเอเชียนเกมส์จบลง ทีมยังมี ไหม-มนัญชญา สว่างแก้ว มือ 88 ของโลก ซึ่งกำลังทำผลงานได้ดี รวมถึงโอกาสในประเภทคู่ที่สมาคมมองว่ายังสามารถลุ้นเหรียญได้</p>\n<p>เทนนิสครั้งนี้มีชิง 5 เหรียญทอง ทั้งชายเดี่ยว หญิงเดี่ยว ชายคู่ หญิงคู่ และคู่ผสม ในอีกมุมหนึ่ง การไม่มีมือ 1 ของประเทศอาจกลายเป็นบททดสอบของเทนนิสไทยด้วยว่า เมื่อผู้เล่นที่ดีที่สุดไม่อยู่ ระบบยังสามารถส่งนักกีฬาคนอื่นขึ้นมารับบทบาทสำคัญได้มากเพียงใด</p>\n<h2>คำถามจึงไม่ควรเป็นว่า ‘ทำไมไม่เล่นเอเชียนเกมส์?’</h2>\n<p>บางทีคำถามที่น่าสนใจกว่าอาจเป็นว่า การตัดสินใจครั้งนี้จะพารวงข้าวไปได้ไกลแค่ไหน เพราะหากเธอสามารถใช้ช่วงเวลานี้ต่อยอดอันดับโลก จากอันดับ 61 เข้าสู่ท็อป 50 เปิดประตูสู่รายการระดับสูงขึ้น และเดินหน้าจนมีโอกาสผ่านเข้าโอลิมปิก 2028 การถอนตัวจากเอเชียนเกมส์ครั้งนี้อาจถูกมองต่างออกไปอย่างสิ้นเชิง</p>\n<p>แต่แน่นอนว่าไม่มีหลักประกันว่าการเลือกเส้นทางนี้จะสำเร็จ และนั่นคือธรรมชาติของกีฬาอาชีพ ที่บางครั้งก็ต้องยอมปล่อยโอกาสที่อยู่ตรงหน้า เพื่อเดิมพันกับโอกาสที่ใหญ่กว่าในอนาคต</p>\n<p>การไม่มีรวงข้าวในเอเชียนเกมส์ 2026 ย่อมเป็นเรื่องน่าเสียดายสำหรับเทนนิสไทย แต่ในเวลาเดียวกัน การมีนักเทนนิสหญิงไทยวัย 22 ปี ขึ้นมาอยู่ถึงอันดับ 61 โลก และกล้าตั้งเป้าหมายต่อไปที่ท็อป 50 กับ โอลิมปิกเกมส์ก็คือสถานการณ์ที่วงการเทนนิสไทยไม่ได้พบเห็นบ่อยนัก</p>\n<p>ในโลกที่โอซากะกับรีบาคินา และนักเทนนิสชั้นนำต้องเลือกปฏิทินของตัวเองเช่นกัน การถอนตัวจึงไม่จำเป็นต้องถูกตีความว่าเป็นการเลือกระหว่าง ‘ตัวเอง’ กับ ‘ประเทศ’</p>\n<p>สำหรับรวงข้าว มันอาจเป็นเพียงการเลือกเส้นทางอีกสายหนึ่งเพื่อไปสู่เป้าหมายเดียวกัน เพียงแต่แทนที่จะผ่านนาโกย่าในปี 2026</p>\n<p>ปลายทางที่เธอกำลังมองอยู่ คือลอสแองเจลิส ในปี 2028 ต่างหาก</p>","1255535":"<p>🏐🇹🇭 โปรแกรมวอลเลย์บอลหญิงไทย <a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a></p>\n<p>วันนี้ทีมวอลเลย์บอลหญิงไทยลงสนามนัดแรกในศึกเอเชียนเกมส์ 2026 พบกับมองโกเลีย เวลา 14.00 น. ที่ Okazaki Chuo Sogo Park Gymnasium เมืองโอกาซากิ จังหวัดไอจิ ประเทศญี่ปุ่น ถ่ายทอดสดทาง PPTV HD 36</p>\n<p>สาวไทยอยู่ในกลุ่ม C ร่วมกับมองโกเลีย, คีร์กีซสถาน และไชนีสไทเป โดยสองทีมอันดับแรกของกลุ่มจะผ่านเข้าสู่รอบ 8 ทีมสุดท้าย</p>\n<p>ตลอดเอเชียนเกมส์ 3 ครั้งที่ผ่านมา ไทยขึ้นโพเดียมได้ทุกครั้ง จากเหรียญทองแดงปี 2014 สู่เหรียญเงินปี 2018 และเหรียญทองแดงปี 2022</p>\n<p>ครั้งนี้สาวไทยกลับมาพร้อมเป้าหมายล่าเหรียญทองเอเชียนเกมส์ครั้งแรกในประวัติศาสตร์ หลังเพิ่งสร้างประวัติศาสตร์คว้าตั๋วไปโอลิมปิกเกมส์ 2028 ได้สำเร็จ</p>\n<p>ร่วมส่งแรงเชียร์ให้ทีมวอลเลย์บอลหญิงไทย ประเดิมเอเชียนเกมส์ 2026 วันนี้ 14.00 น. ถ่ายทอดสดทาง PPTV HD 36</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/thai-women-volleyball-asian-games-2026-1.jpg\" alt=\"ภาพกราฟิกโปรแกรมการแข่งขันวอลเลย์บอลหญิงไทยในเอเชียนเกมส์ 2026 พร้อมรูปนักกีฬา 1\" width=\"850\" height=\"1063\" /></p>","1255360":"<p>‘รวงข้าว’ ลัลนา ธาราฤดี นักเทนนิสหญิงไทย เข้าพบ ภูริต ภิรมย์ภักดี กรรมการผู้จัดการใหญ่ บริษัท บุญรอดบริวเวอรี่ จำกัด เพื่อขอบคุณสำหรับการสนับสนุน หลังทำผลงานดีที่สุดในเส้นทางอาชีพ ขยับขึ้นสู่อันดับ 61 ของโลก</p>\n<p>อันดับดังกล่าวทำให้ลัลนากลายเป็นนักเทนนิสหญิงไทยที่เคยทำอันดับโลกสูงสุดเป็นอันดับ 2 ในประวัติศาสตร์ รองจาก ‘แทมมี่’ แทมมารีน ธนสุกาญจน์ ที่เคยขึ้นไปถึงมือ 19 ของโลก</p>\n<p>สำหรับปี 2026 ลัลนาลงเล่นแกรนด์สแลม 3 รายการ โดยผ่านเข้าสู่รอบแรก<a href=\"https://thestandard.co/tag/Australian-Open/\" target=\"_blank\" rel=\"noopener\">ออสเตรเลียน โอเพ่น</a> ก่อนเข้าถึงรอบสองทั้งวิมเบิลดันและยูเอส โอเพ่น ซึ่งผลงานจากรายการล่าสุดส่งให้เธอขยับขึ้น 15 อันดับ จากมือ 76 สู่มือ 61 ของโลก</p>\n<p>ลัลนาเป็นหนึ่งในนักเทนนิสที่ได้รับการสนับสนุนจากสิงห์มาตั้งแต่ระดับเยาวชน และเคยเข้าร่วมโครงการ Singha Grand Slam Experience เพื่อสัมผัสการแข่งขันออสเตรเลียน โอเพ่น ที่ออสเตรเลียเมื่อปี 2019 ก่อนพัฒนาฝีมือจนก้าวขึ้นมาแข่งขันในระดับแกรนด์สแลม</p>\n<p>ขณะเดียวกัน ‘ไหม’ มนัญชญา สว่างแก้ว อีกหนึ่งนักเทนนิสหญิงไทยที่ผ่านเข้าสู่รอบสองยูเอส โอเพ่น 2026 เช่นกัน ขยับจากมือ 95 ขึ้นมาอยู่มือ 88 ของโลก ซึ่งเป็นอันดับสูงสุดในอาชีพของเจ้าตัว</p>","1255202":"<p>‘ต่อ’ <a href=\"https://thestandard.co/tag/%E0%B9%80%E0%B8%89%E0%B8%A5%E0%B8%B4%E0%B8%A1%E0%B8%89%E0%B8%B2%E0%B8%99-%E0%B8%A2%E0%B8%A8%E0%B8%A7%E0%B8%B4%E0%B8%A3%E0%B8%B4%E0%B8%A2%E0%B8%B0%E0%B8%9E%E0%B8%B2%E0%B8%93%E0%B8%B4%E0%B8%8A%E0%B8%A2%E0%B9%8C/\" target=\"_blank\" rel=\"noopener\">เฉลิมฉาน ยศวิริยะพาณิชย์</a> นักกีฬาขี่ม้า และ ‘แนน’ ทัดดาว นึกแจ้ง นักวอลเลย์บอลหญิงทีมชาติไทย ได้รับเลือกให้เป็นผู้ถือธงชาติไทย นำทัพนักกีฬาเข้าสู่พิธีเปิดเอเชียนเกมส์ ครั้งที่ 20 ที่ประเทศญี่ปุ่น วันที่ 19 กันยายนนี้</p>\n<p>เฉลิมฉานเป็นนักขี่ม้ามากประสบการณ์ของทีมชาติไทย เคยคว้าเหรียญเงินประเภททีม ศิลปะการบังคับม้า ในเอเชียนเกมส์ 2018 ที่อินโดนีเซีย รวมถึงเหรียญทองซีเกมส์ ครั้งที่ 33</p>\n<p>ขณะที่ทัดดาวเป็นหนึ่งในกำลังสำคัญของทีมวอลเลย์บอลหญิงไทย และมีส่วนพาทีมคว้าแชมป์เอเชีย 2026 พร้อมสร้างประวัติศาสตร์คว้าสิทธิ์ไปแข่งขันโอลิมปิกเกมส์ 2028</p>\n<p>สำหรับพิธีเปิดเอเชียนเกมส์ 2026 จะมีขึ้นวันที่ 19 กันยายน เวลา 16.00 น. ตามเวลาประเทศไทย ที่สนามปาโลมา มิซูโฮะ เมืองนาโกยา จังหวัดไอจิ โดยการแข่งขันจะจัดขึ้นระหว่างวันที่ 19 กันยายน – 4 ตุลาคม 2026</p>\n<p>.</p>","1255198":"<p>Pusha T และ <a href=\"https://thestandard.co/tag/Pharrell-Williams/\" target=\"_blank\" rel=\"noopener\">Pharrell Williams</a> สองศิลปินและผู้ร่วมงานกันมายาวนาน ขยายความสัมพันธ์จากโลกดนตรีสู่ธุรกิจเครื่องดื่ม ด้วยการจับมือกับ Lavazza แบรนด์กาแฟจากอิตาลี เปิดตัว Grindin’ Coffee กาแฟที่สร้างขึ้นสำหรับคนที่ต้องการพลังในการเริ่มต้นและลงมือทำสิ่งต่างๆ ในแต่ละวัน</p>\n<p>Pusha T เปิดเผยกับ GQ ว่า จุดเริ่มต้นของโปรเจกต์นี้ย้อนกลับไปในช่วงการทำอัลบั้ม It’s Almost Dry ระหว่างการทำงานร่วมกับ Pharrell ที่ไมอามี โดยทั้งคู่มีตารางชีวิตคล้ายกัน คือเริ่มต้นวันตั้งแต่เช้าตรู่ด้วยกาแฟดำ ก่อนใช้เวลาราว 7 ชั่วโมงทำเพลง และออกไปปั่นจักรยานประมาณ 20 ไมล์ หรือ 32 กิโลเมตร</p>\n<p>จากกิจวัตรระหว่างการทำเพลง กาแฟค่อยๆ กลายมาเป็นอีกหนึ่งโปรเจกต์ของ Pusha T โดย Grindin’ Coffee เริ่มทดลองตลาดผ่าน Pop-Up ที่เทศกาล Camp Flog Gnaw ติดต่อกันสองปี ซึ่งได้รับความสนใจจากผู้ร่วมงานจำนวนมาก รวมถึงสินค้า Merchandise ที่ทำร่วมกับ Carhartt</p>\n<p>ต่อมา Pharrell ได้เชื่อมต่อโปรเจกต์กับ Lavazza แบรนด์กาแฟอิตาลีที่มีประวัติยาวนานกว่า 130 ปี ก่อนที่ทั้งสองฝ่ายจะพัฒนาความร่วมมือจนกลายเป็น Grindin’ Coffee ในรูปแบบปัจจุบัน</p>\n<p>สำหรับชื่อ Grindin’ ยังเชื่อมโยงกลับไปถึง “Grindin’” หนึ่งในเพลงสำคัญของ Clipse ซึ่ง Pharrell เป็นโปรดิวเซอร์ และกลายเป็นการนำมรดกทางดนตรีของ Pusha T และ Pharrell มาต่อยอดเป็นแบรนด์กาแฟที่สะท้อนแนวคิดเรื่องการทำงาน ความมุ่งมั่น และการลงมือทำ</p>\n<p><span><b><span><strong>อ้างอิง</strong></span></b></span></p>\n<ul>\n<li><b></b><b><a href=\"https://www.gq.com/story/pusha-t-tap-in\" target=\"_blank\" rel=\"noopener\">https://www.gq.com/story/pusha-t-tap-in</a></b><b> </b></li>\n</ul>\n<p><span><strong>ภาพ:</strong><span> grindin / Instagram</span></span></p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-1.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 1\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-2.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 2\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-3.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 3\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-4.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 4\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-5.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 5\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-6.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 6\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-7.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 7\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-8.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 8\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-9.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 9\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-10.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 10\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-11.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 11\" width=\"850\" height=\"1063\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/pusha-t-pharrell-lavazza-grindin-coffee-12.jpg\" alt=\"ภาพ Pusha T และ Pharrell Williams พร้อมโลโก้ Grindin’ Coffee 12\" width=\"850\" height=\"1063\" /></p>","1255174":"<p>Koala Japan แบรนด์ที่นอน เตรียมจัดการแข่งขันรูปแบบแปลกใหม่ในชื่อ ‘Mattrace by Koala’ ที่กรุงโตเกียว <a href=\"https://thestandard.co/tag/Japan/\" target=\"_blank\" rel=\"noopener\">ประเทศญี่ปุ่น</a> วันที่ 5 ตุลาคมนี้ โดยผู้เข้าแข่งขันไม่ต้องวิ่งหรือใช้พละกำลัง แต่ต้องแข่งขันกันว่าใครสามารถ ‘นอนหลับได้ดีที่สุด’ ภายในเวลา 90 นาที เพื่อชิงเงินรางวัล 2.22 ล้านเยน หรือกว่า 4 แสนบาท</p>\n<p>การแข่งขันจะจัดขึ้นที่ แชร์ กรีน มินามิ อาโอะยามะ ในเขตมินาโตะ แบ่งออกเป็น 3 รอบ รอบละประมาณ 20 คน โดยผู้เข้าแข่งขันทุกคนจะสวมอุปกรณ์ติดตามการนอน ก่อนขึ้นไปนอนบนที่นอนของ Koala</p>\n<p>ผลการแข่งขันจะตัดสินผ่าน ‘Sleep Score’ ซึ่งประเมินจากหลายปัจจัย ทั้งระดับความลึกของการหลับ คุณภาพการนอน ระยะเวลาที่ใช้ก่อนหลับ และความต่อเนื่องของการนอน โดย Koala ระบุว่าระบบการให้คะแนนได้รับการดูแลโดยแพทย์ และผู้ทำคะแนนรวมสูงที่สุดจะคว้าเงินรางวัล 2.22 ล้านเยน</p>\n<p>อย่างไรก็ตาม การแข่งขันไม่ได้ง่ายเพียงแค่ขึ้นเตียงแล้วหลับ เพราะก่อนเริ่มผู้เข้าแข่งขันจะต้องผ่านกิจกรรม ‘Sleep Warm-Up’ และได้รับอุปกรณ์บางอย่างที่อาจส่งผลต่อการนอน ขณะที่ระหว่างการแข่งขัน ฝ่ายจัดจะสร้างสิ่งรบกวนขึ้นมาเพื่อทดสอบว่าแต่ละคนสามารถรักษาคุณภาพการหลับไว้ได้ดีเพียงใด</p>\n<p>นอกจากรางวัลใหญ่ ยังมีรางวัลพิเศษอย่าง ‘Deep Sleep Award’ สำหรับผู้ที่สามารถเข้าสู่ภาวะหลับลึกได้โดดเด่น และ ‘Sleep Flip Award’ สำหรับผู้เข้าแข่งขันที่มีท่าทางการนอนเป็นเอกลักษณ์</p>\n<p>Mattrace by Koala จะเปิดรับสมัครถึงวันที่ 16 กันยายน เวลา 23.59 น. ตามเวลาญี่ปุ่น และหากมีผู้สมัครมากกว่าจำนวนที่กำหนดจะใช้วิธีจับสลากคัดเลือก ก่อนจัดการแข่งขันจริงในวันที่ 5 ตุลาคมนี้</p>\n<p><span><b><span><strong>อ้างอิง</strong></span></b></span></p>\n<ul>\n<li><b></b><b><a href=\"https://www.tokyoweekender.com/japan-life/news-and-opinion/tokyo-sleep-race-with-2-million-yen-prize/\" target=\"_blank\" rel=\"noopener\">https://www.tokyoweekender.com/japan-life/news-and-opinion/tokyo-sleep-race-with-2-million-yen-prize/</a></b></li>\n</ul>\n<p><span><strong>ภาพ:</strong><span> Flashpop / Getty Images</span></span></p>","1255098":"<p>เหรียญรางวัลคือหนึ่งในสิ่งที่นักกีฬาทุกคนอยากคว้ากลับบ้านจากเอเชียนเกมส์ แต่สำหรับ Aichi-Nagoya 2026 เจ้าภาพเลือกออกแบบเหรียญให้มีรูปทรงคล้ายชิ้นส่วนที่แตกออกจากกัน ก่อนนำกลับมาประกอบเป็นหนึ่งเดียว</p>\n<p>ที่น่าสนใจคือ รูปทรงเหล่านั้นไม่ได้เกิดขึ้นจากการวาดขึ้นมาเพียงอย่างเดียว เพราะระหว่างการออกแบบ มีการนำแผ่นเซรามิกมาทุบซ้ำๆ เพื่อค้นหารูปทรงที่เหมาะสม และใช้ ‘เศษที่แตก’ เปรียบกับอุปสรรคและความท้าทายที่นักกีฬาต้องผ่านกว่าจะมาถึงวันที่ได้ยืนบนโพเดียม</p>\n<p>THE STANDARD SPORT ชวนดูเบื้องหลังเหรียญรางวัลของ Aichi-Nagoya 2026 ว่าทำไม ‘รอยแตก’ จึงกลายมาเป็นส่วนสำคัญของเหรียญแห่งความสำเร็จนี้</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-medal-cracks-design-1.jpg\" alt=\"ภาพเหรียญรางวัลเอเชียนเกมส์ 2026 ที่มีดีไซน์เป็นชิ้นส่วนรอยแตกประกอบกัน 1\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-medal-cracks-design-2.jpg\" alt=\"ภาพเหรียญรางวัลเอเชียนเกมส์ 2026 ที่มีดีไซน์เป็นชิ้นส่วนรอยแตกประกอบกัน 2\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-medal-cracks-design-3.jpg\" alt=\"ภาพเหรียญรางวัลเอเชียนเกมส์ 2026 ที่มีดีไซน์เป็นชิ้นส่วนรอยแตกประกอบกัน 3\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-medal-cracks-design-4.jpg\" alt=\"ภาพเหรียญรางวัลเอเชียนเกมส์ 2026 ที่มีดีไซน์เป็นชิ้นส่วนรอยแตกประกอบกัน 4\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-medal-cracks-design-5.jpg\" alt=\"ภาพเหรียญรางวัลเอเชียนเกมส์ 2026 ที่มีดีไซน์เป็นชิ้นส่วนรอยแตกประกอบกัน 5\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-medal-cracks-design-6.jpg\" alt=\"ภาพเหรียญรางวัลเอเชียนเกมส์ 2026 ที่มีดีไซน์เป็นชิ้นส่วนรอยแตกประกอบกัน 6\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-medal-cracks-design-7.jpg\" alt=\"ภาพเหรียญรางวัลเอเชียนเกมส์ 2026 ที่มีดีไซน์เป็นชิ้นส่วนรอยแตกประกอบกัน 7\" width=\"1080\" height=\"1350\" /></p>","1255071":"<p>โนวัค ยอโควิช หลุดจากการเป็นมือวาง 10 อันดับแรกในการจัดอันดับโลกของ ATP นับตั้งแต่ปี 2018 หลังตกรอบแรกเทนนิส ยูเอสโอเพน 2026 ส่งผลให้เป็นครั้งแรกในรอบเกือบ 24 ปีที่ไม่มีชื่อนักเทนนิส BIG 3 ทั้ง <a href=\"https://thestandard.co/tag/Roger-Federer/\" target=\"_blank\" rel=\"noopener\">โรเจอร์ เฟเดอเรอร์</a>, ราฟาเอล นาดาล และ โนเล่ อยู่ใน 10 อันดับแรกของโลก</p>\n<p>นักเทนนิสชาวเซอร์เบียไม่สามารถป้องกันคะแนนจากการเข้าถึงรอบรองชนะเลิศเมื่อปีที่แล้ว หลังพ่าย มาเรียโน นาโวเน ในรอบแรก 2-3 เซต ในการแข่งขันที่กินเวลานานกว่า 4 ชั่วโมงครึ่ง ก่อนอันดับโลกของเขาจะร่วงออกจาก ท็อป 10 ในการประกาศอันดับล่าสุด</p>\n<p>การหลุดจาก 10 อันดับแรกของยอโควิชยังทำให้สถิติอันยาวนานของ Big 3 สิ้นสุดลง โดยนับตั้งแต่เดือนตุลาคม 2002 เป็นต้นมา จะมีสมาชิกอย่างน้อยหนึ่งคนจาก เฟเดอเรอร์, นาดาล และ ยอโควิช อยู่ใน 10 อันดับแรกของ ATP มาโดยตลอด</p>\n<p>เฟ็ดเอ็กซ์ เป็นผู้เริ่มต้นสถิตินี้ หลังเข้าสู่ Top 10 ในเดือนตุลาคม 2002 และรักษาตำแหน่งไว้จนถึงเดือนพฤศจิกายน 2016 ขณะที่ นาดาล เข้าสู่ Top 10 ในเดือนเมษายน 2005 และสร้างสถิติอยู่ในกลุ่มดังกล่าวติดต่อกันมากกว่า 900 สัปดาห์ ก่อนหลุดออกมาในเดือนมีนาคม 2023</p>\n<p>ส่วนยอโควิชเข้าสู่ Top 10 ครั้งแรกเมื่อเดือนมีนาคม 2007 ก่อนหลุดออกไปจากปัญหาอาการบาดเจ็บ และกลับมาอีกครั้งหลังคว้าแชมป์ วิมเบิลดัน เมื่อเดือนกรกฎาคม 2018 จากนั้นรักษาอันดับใน Top 10 ต่อเนื่องมาจนถึง ยูเอสโอเพน 2026</p>\n<p>ในช่วงหลัง ยอโควิชลดจำนวนทัวร์นาเมนต์ที่ลงแข่งขันเพื่อรักษาสภาพร่างกาย และให้ความสำคัญกับรายการระดับแกรนด์สแลมเป็นหลัก อย่างไรก็ตาม การตกรอบแรกที่นิวยอร์ก ซึ่งถือเป็นการพ่ายแพ้ในแกรนด์สแลมที่เร็วที่สุดของเขานับตั้งแต่ปี 2006 ทำให้คะแนนไม่เพียงพอสำหรับการรักษาสถานะท็อป 10 ไว้ได้</p>\n<p><span><b><span><strong>อ้างอิง</strong></span></b></span></p>\n<ul>\n<li><span><b><a href=\"https://www.tennisworldusa.org/tennis/news/Novak_Djokovic/169628/novak-djokovic-falls-out-of-top10-as-big-3-era-finally-ends/\" target=\"_blank\" rel=\"noopener\">https://www.tennisworldusa.org/tennis/news/Novak_Djokovic/169628/novak-djokovic-falls-out-of-top10-as-big-3-era-finally-ends/</a> </b></span></li>\n</ul>\n<p><span><strong>ภาพ:</strong><span> Julian Finney / Getty Images</span></span></p>","1255064":"<p><a href=\"https://thestandard.co/tag/Aim%C3%A9-Leon-Dore/\" target=\"_blank\" rel=\"noopener\">Aimé Leon Dore</a> และ The North Face สร้างความสนใจก่อนเปิดตัวคอลเล็กชัน Collaboration ใหม่ ด้วยการนำเฮลิคอปเตอร์ที่ตกแต่งด้วยแบรนดิ้งของทั้งสองแบรนด์มาจอดบริเวณหน้าร้าน Flagship ของ Aimé Leon Dore ในนิวยอร์ก</p>\n<p><a href=\"#photos\" target=\"_blank\" rel=\"noopener\"><img src=\"https://unpkg.com/lucide-static/icons/camera.svg\" alt=\"\" />ดูภาพข่าว</a> </p>\n<p>เฮลิคอปเตอร์ลำดังกล่าวถูกตกแต่งด้วยโลโก้ The North Face, Aimé Leon Dore และ GORE-TEX กลายเป็นส่วนหนึ่งของโปรเจกต์ร่วมกันที่กำลังจะเปิดตัว และเปลี่ยนพื้นที่หน้าร้านให้กลายเป็นแคมเปญโปรโมตที่สะดุดตากว่าการเปิดตัวผ่านหน้าร้านในรูปแบบทั่วไป</p>\n<p>เฮลิคอปเตอร์ลำนี้ คาดว่าน่าจะเป็นลำเดียวกับที่ปรากฎในทีเซอร์โปรโมตคอลเล็กชัน Aimé Leon Dore x The North Face 2026 ซึ่งมีเนื้อหาที่ ฮ. ลำดังกล่าวบินไปรับกระเป๋า North Face จากบนภูเขาหิมะมาส่งในมหานครนิวยอร์ก</p>\n<p>การเคลื่อนไหวครั้งนี้เป็นอีกหนึ่งวิธีที่ Aimé Leon Dore ใช้สร้างกระแสให้กับการร่วมงานกับ The North Face ก่อนที่รายละเอียดของสินค้าในคอลเล็กชันจะถูกเปิดเผยเพิ่มเติม</p>\n<p>สำหรับคอลเล็กชัน Aimé Leon Dore x The North Face มีกำหนดวางจำหน่ายอย่างเป็นทางการในวันที่ 18 กันยายนนี้</p>\n<p><span><strong>ภาพ:</strong><span> slimcargos / Instagram</span></span></p>\n \n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aime-leon-dore-north-face-helicopter-new-york-1.jpg\" alt=\"เฮลิคอปเตอร์ตกแต่งโลโก้ Aimé Leon Dore และ The North Face จอดอยู่หน้าร้านในนิวยอร์ก 1\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aime-leon-dore-north-face-helicopter-new-york-2.jpg\" alt=\"เฮลิคอปเตอร์ตกแต่งโลโก้ Aimé Leon Dore และ The North Face จอดอยู่หน้าร้านในนิวยอร์ก 2\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aime-leon-dore-north-face-helicopter-new-york-3.jpg\" alt=\"เฮลิคอปเตอร์ตกแต่งโลโก้ Aimé Leon Dore และ The North Face จอดอยู่หน้าร้านในนิวยอร์ก 3\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aime-leon-dore-north-face-helicopter-new-york-4.jpg\" alt=\"เฮลิคอปเตอร์ตกแต่งโลโก้ Aimé Leon Dore และ The North Face จอดอยู่หน้าร้านในนิวยอร์ก 4\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aime-leon-dore-north-face-helicopter-new-york-5.jpg\" alt=\"เฮลิคอปเตอร์ตกแต่งโลโก้ Aimé Leon Dore และ The North Face จอดอยู่หน้าร้านในนิวยอร์ก 5\" width=\"850\" height=\"1080\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aime-leon-dore-north-face-helicopter-new-york-6.jpg\" alt=\"เฮลิคอปเตอร์ตกแต่งโลโก้ Aimé Leon Dore และ The North Face จอดอยู่หน้าร้านในนิวยอร์ก 6\" width=\"850\" height=\"1080\" /></p>","1255054":"<p>ฝ่ายจัดการแข่งขัน <a href=\"https://thestandard.co/tag/Spanish-Grand-Prix/\" target=\"_blank\" rel=\"noopener\">สแปนิช กรังด์ปรีซ์</a> เตรียมพิจารณาปรับเลย์เอาต์ของสนามมาดริงสำหรับฤดูกาลหน้า หลังการแข่งขัน F1 ครั้งแรกที่กรุงมาดริดได้รับเสียงวิจารณ์จากนักขับเรื่องโอกาสในการแซงที่มีจำกัด</p>\n<p>แม้นักขับหลายคนจะชื่นชมความท้าทายของสนามในการขับรอบควอลิฟายด์ แต่การแข่งขันจริงกลับเกิดการแซงได้ยาก โดยอเล็กซ์ อัลบอน จากทีมวิลเลียมส์ มองว่าเรซค่อนข้างน่าเบื่อ ขณะที่ กาเบรียล บอร์โตเลโต จากทีมอาวดี้ ระบุว่าแทบจะหลับระหว่างการแข่งขัน</p>\n<p>ด้าน แลนโด นอร์ริส แชมป์โลก F1 ฤดูกาลที่ผ่านมา มองว่าสนามมีศักยภาพที่จะพัฒนาได้อีกมาก โดยเฉพาะบริเวณโค้ง 18 และ 19 ซึ่งเขาเสนอให้ตัดออกและเปลี่ยนเป็นทางตรง เพื่อเพิ่มโอกาสในการแซง พร้อมยืนยันว่าสนามแห่งนี้สนุกสำหรับการขับหนึ่งรอบ แต่ยังไม่เหมาะกับการแข่งขันเท่าที่ควร</p>\n<p>ขณะที่ คิมี อันโตเนลลี ผู้ชนะการแข่งขันก็มีความเห็นในทิศทางเดียวกัน โดยมองว่ารูปแบบสนามปัจจุบันไม่ได้กระตุ้นให้นักขับพยายามแซง เนื่องจากหลายจุดมีความเสี่ยงต่อการปะทะสูง ทำให้รถส่วนใหญ่ต้องติดอยู่ด้านหลังคู่แข่งระหว่างการแข่งขัน</p>\n<p>โดยทาง หลุยส์ การ์เซีย อาบัด กรรมการผู้จัดการสนามมาดริง เปิดเผยหลังการแข่งขันว่า FIA ได้ให้แนวทางเบื้องต้นสำหรับการพัฒนาสนามแล้ว และผู้จัดพร้อมทำงานร่วมกับ FIA เพื่อหาจุดที่สามารถปรับปรุงได้ก่อนการแข่งขันครั้งต่อไป</p>\n<p>นอกจากประเด็นในสนามแล้ว แฟน F1 บนโซเชียลมีเดียยังวิจารณ์เรื่องการเดินทางเข้าสนาม, ทัศนวิสัยจากพื้นที่ชมการแข่งขัน และสิ่งอำนวยความสะดวกบางส่วน โดยการแข่งขันครั้งแรกเกิดขึ้นภายใต้กรอบเวลาเตรียมงานที่ค่อนข้างจำกัด</p>\n<p>สำหรับมาดริงเป็นสนามกึ่งถาวรที่ผสมผสานถนนเดิมรอบศูนย์ประชุม IFEMA เข้ากับส่วนของสนามที่สร้างขึ้นใหม่ รวมถึง La Monumental โค้งเอียงซึ่งเป็นหนึ่งในเอกลักษณ์สำคัญของสนาม โดยฝ่ายจัดยืนยันว่ามีทั้งพื้นที่และศักยภาพเพียงพอที่จะปรับปรุงสนามสำหรับ สแปนิช กรังด์ปรีซ์ ในปี 2027</p>\n<p><span><b><span><strong>อ้างอิง</strong></span></b></span></p>\n<ul>\n<li><b></b><b><a href=\"https://www.bbc.com/sport/formula1/articles/ckwyzllzdq43o\" target=\"_blank\" rel=\"noopener\">https://www.bbc.com/sport/formula1/articles/ckwyzllzdq43o</a></b></li>\n</ul>\n<p><span><strong>ภาพ:</strong><span> Kym Illman / Getty Images</span></span></p>","1254944":"<p><a href=\"https://thestandard.co/tag/Asian-Games-2026/\" target=\"_blank\" rel=\"noopener\">เอเชียนเกมส์ 2026</a> ที่ Aichi-Nagoya กำลังเปิดฉาก พร้อมกับการมาถึงของกีฬาใหม่ที่ถูกบรรจุเข้าสู่การแข่งขันเป็นครั้งแรก</p>\n<p>ตั้งแต่เทคบอล พาเดล และ MMA ไปจนถึงเทควันโดเสมือนจริง บางชนิดกำลังเติบโตในระดับโลก ขณะที่บางชนิดถือเป็นอีกหนึ่งความหวังในการลุ้นเหรียญของทัพนักกีฬาไทย</p>\n<p>THE STANDARD SPORT ชวนรู้จัก 6 กีฬาใหม่ ที่เตรียมสร้างประวัติศาสตร์บนเวทีเอเชียนเกมส์ครั้งนี้</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-new-sports-1.jpg\" alt=\"ภาพประกอบ 6 กีฬาใหม่ในเอเชียนเกมส์ 2026 ที่ Aichi-Nagoya 1\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-new-sports-2.jpg\" alt=\"ภาพประกอบ 6 กีฬาใหม่ในเอเชียนเกมส์ 2026 ที่ Aichi-Nagoya 2\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-new-sports-3.jpg\" alt=\"ภาพประกอบ 6 กีฬาใหม่ในเอเชียนเกมส์ 2026 ที่ Aichi-Nagoya 3\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-new-sports-4.jpg\" alt=\"ภาพประกอบ 6 กีฬาใหม่ในเอเชียนเกมส์ 2026 ที่ Aichi-Nagoya 4\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-new-sports-5.jpg\" alt=\"ภาพประกอบ 6 กีฬาใหม่ในเอเชียนเกมส์ 2026 ที่ Aichi-Nagoya 5\" width=\"1080\" height=\"1350\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/asian-games-2026-new-sports-6.jpg\" alt=\"ภาพประกอบ 6 กีฬาใหม่ในเอเชียนเกมส์ 2026 ที่ Aichi-Nagoya 6\" width=\"1080\" height=\"1350\" /></p>","1254920":"<p>วันนี้ (14 กันยายน) <a href=\"https://thestandard.co/tag/%E0%B8%9F%E0%B8%B8%E0%B8%95%E0%B8%9A%E0%B8%AD%E0%B8%A5%E0%B8%AB%E0%B8%8D%E0%B8%B4%E0%B8%87%E0%B8%97%E0%B8%B5%E0%B8%A1%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B9%84%E0%B8%97%E0%B8%A2/\" target=\"_blank\" rel=\"noopener\">ฟุตบอลหญิงทีมชาติไทย</a> ลงสนามนัดแรกในศึกเอเชียนเกมส์ 2026 รอบแบ่งกลุ่ม กลุ่ม E พบกับเจ้าภาพญี่ปุ่น</p>\n<p>โดยเกมนี้ทัพชบาแก้วต้านความแข็งแกร่งของเจ้าภาพไม่ไหว ถูกยิง 4 ประตูในครึ่งแรก ก่อนเสียเพิ่มอีก 4 ประตูในครึ่งหลัง จบเกมพ่ายไป 0-8 ทำให้ยังไม่มีคะแนนจากเกมเปิดสนาม</p>\n<p>สำหรับโปรแกรมนัดต่อไป ทีมชาติไทยจะพบกับ ไชนีส ไทเป ในวันที่ 17 กันยายน เวลา 14.00 น. ตามเวลาประเทศไทย ถ่ายทอดสดทาง MCOT HD ช่อง 30 และ AIS PLAY</p>","1254830":"<p>เหลืออีกเพียงไม่กี่วัน… เอเชียนเกมส์ 2026 กำลังเปิดฉากขึ้นที่ Aichi-Nagoya ประเทศญี่ปุ่น พร้อมการรวมตัวของนักกีฬาจากทั่วเอเชียเพื่อชิงชัยในมหกรรมกีฬาครั้งใหญ่ของทวีป</p>\n<p>แต่ก่อนการแข่งขันจะเข้มข้นขึ้น THE STANDARD SPORT ชวนมองอีกหนึ่งรายละเอียดของเจ้าภาพครั้งนี้ ผ่านงานออกแบบที่ปรากฏอยู่รอบการแข่งขัน ตั้งแต่ตราสัญลักษณ์ สี สโลแกน มาสคอต พิกโตแกรม คบเพลิง ไปจนถึงเหรียญรางวัล</p>\n<p>เพราะเบื้องหลังสีและเส้นสายเหล่านี้ ล้วนมีเรื่องราวของ Aichi-Nagoya ซ่อนอยู่อย่างน่าสนใจ..</p>\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-1.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 1\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-2.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 2\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-3.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 3\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-4.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 4\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-5.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 5\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-6.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 6\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-7.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 7\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-8.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 8\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-9.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 9\" width=\"850\" height=\"1062\" /><img src=\"https://thestandard.co/wp-content/uploads/2026/09/aichi-nagoya-2026-asian-games-design-10.jpg\" alt=\"ภาพปก Aichi-Nagoya 2026 แสดงดีไซน์ตราสัญลักษณ์ สี และมาสคอตของการแข่งขัน 10\" width=\"850\" height=\"1062\" /></p>","1254726":"<p>ตารางคะแนนสะสมประเภทผู้สร้าง (Constructors’ Championship) หลังจบ <a href=\"https://thestandard.co/tag/Spanish-Grand-Prix/\" target=\"_blank\" rel=\"noopener\">Spanish Grand Prix 2026</a> ที่ MADRING ยังคงเป็น Mercedes ที่นำเป็นจ่าฝูง หลัง คิมี อันโตเนลลี คว้าชัยชนะ ขณะที่ จอร์จ รัสเซลล์ เข้าเส้นชัยในอันดับ 5 ช่วยให้ทีมขยับไปมี 503 คะแนน</p>\n<p>ด้าน Ferrari ยังคงรั้งอันดับ 2 ที่ 358 คะแนน ตามมาด้วย McLaren ในอันดับ 3 ที่ 306 คะแนน</p>\n<p>และนี่คือภาพรวมของ World Constructors’ Championship Standings หลังจบการแข่งขัน F1 ครั้งแรกที่ MADRING</p>\n<hr />\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/f1-constructors-standings-spanish-1-1.jpg\" alt=\"ภาพรถแข่ง F1 ปี 2026 1\" width=\"1080\" height=\"1350\" /></p>","1254720":"<p>คิมี อันโตเนลลี จารึกชื่อเป็นนักขับคนแรกที่คว้าชัยชนะใน Spanish GP บนสนาม MADRING หลังพา Mercedes เข้าเส้นชัยเป็นอันดับ 1 ในการแข่งขันครั้งแรกของ F1 ที่สนามแห่งใหม่ในกรุงมาดริด</p>\n<p>ชัยชนะครั้งนี้ยังช่วยให้ อันโตเนลลี ขยับเข้าใกล้แชมป์โลก F1 ฤดูกาล 2026 มากขึ้น พร้อมทิ้งห่าง <a href=\"https://thestandard.co/tag/George-Russell/\" target=\"_blank\" rel=\"noopener\">จอร์จ รัสเซลล์</a> เพื่อนร่วมทีมและอันดับ 2 เพิ่มเป็น 81 คะแนน ขณะที่เหลือการแข่งขันอีก 9 สนาม</p>\n<p>และนี่คือภาพรวม World Drivers’ Championship Standings หลังจบการแข่งขันที่ MADRING</p>\n<hr />\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/antonelli-f1-spanish-gp-standings-1.jpg\" alt=\"คิมี อันโตเนลลี นักแข่ง F1 ทีม Mercedes ในชุดแข่งขณะแข่งขัน Spanish GP 2026 1\" width=\"1080\" height=\"1350\" /></p>","1254703":"<p>แกรนด์สแลมทั้ง 4 รายการของปี 2026 ก็ปิดฉากจบลงไปแล้วทุกรายการ ทำให้ตอนนี้เราได้เห็นหน้านักเทนนิสเจ้าของแชมป์แกรนด์สแลมในปีนี้ทั้ง <a href=\"https://thestandard.co/tag/Australian-Open/\" target=\"_blank\" rel=\"noopener\">ออสเตรเลียนโอเพน</a>, เฟรนช์โอเพน, วิมเบิลดัน และ ยูเอสโอเพน</p>\n<hr />\n<p><img src=\"https://thestandard.co/wp-content/uploads/2026/09/FB_SPORT_INFO_แชมป์แกรนด์สแลม-2026_INFO-Sport-1.jpg\" alt=\"\" width=\"1080\" height=\"1350\" /></p>\n<p><span>ภาพประกอบ: กริน วสุรัฐกร</span></p>"};
